     hints:["برای (الف): $I_0(z)$ در $z\\to0$ به چه مقداری میل می‌کند؟ سری تیلورش را بنویسید: $I_0(z)=1+z^2/4+\\cdots$.",
            "با $\\nu\\to0$ هم $I_0(r\\nu/\\sigma^2)\\to1$ و هم $e^{-\\nu^2/2\\sigma^2}\\to1$. چه می‌ماند؟",
            "برای (ب): $K$ بزرگ یعنی توان مؤلفهٔ قطعی بسیار بیشتر از توان پراکنده. انتظار دارید دامنه حول چه مقداری متمرکز شود و پهنای آن چقدر باشد؟"],
