    {level:4, skill:"تشخیص مدل از داده — سؤال امتحانی", prereqs:["pdf","cdf"],
     q:"دو مجموعه اندازه‌گیری از دامنهٔ دریافتی دارید. در مجموعهٔ اول، نسبت $E[R^2]/(E[R])^2$ تقریباً $4/\\pi\\approx1.273$ است. در مجموعهٔ دوم این نسبت $1.02$ است. بدون برازش هیچ توزیعی، دربارهٔ وجود مسیر دید مستقیم در هر کانال چه می‌گویید؟ پاسخ را با محاسبه توجیه کنید و بگویید چه فرضی را ناگفته پذیرفته‌اید.",
     hints:["برای رایلی، $E[R]=\\sigma\\sqrt{\\pi/2}$ و $E[R^2]=2\\sigma^2$. نسبت خواسته‌شده را برای رایلی حساب کنید.",
            "نسبتی که به ۱ نزدیک است یعنی واریانس نسبی بسیار کوچک است: $E[R^2]/(E[R])^2=1+\\mathrm{Var}(R)/(E[R])^2$. چه زمانی واریانس دامنه تقریباً صفر می‌شود؟",
            "فرض ناگفته: این نسبت فقط وقتی تشخیص‌دهنده است که بدانید توزیع از خانوادهٔ رایسین است. چه توزیع دیگری می‌تواند همین نسبت را بدهد؟"],
     verify:"بررسی: نسبت $4/\\pi$ امضای دقیق رایلی ($K=0$) است و نسبت نزدیک به ۱ یعنی $K$ بسیار بزرگ. این یک «آمارهٔ بدون مقیاس» است: به $\\sigma$ بستگی ندارد، که همان چیزی است که آن را مفید می‌کند."}
