/* ---------- prereq cards ---------- */
function renderPre(){
  $("#preCards").innerHTML = PREREQS.map(function(p){
    var v = ST.pre[p.id]||0;
    return '<div class="ex"><div class="hd"><span class="id">'+p.id.toUpperCase()+'</span>'+
      '<b style="font-size:15px">'+p.n+'</b>'+
      '<span class="st"><span class="pill '+(v===0?"":v<3?"no":v===3?"mid":"ok")+'">'+
        (v===0?"ارزیابی‌نشده":v===1?"بلد نیستم":v===2?"ضعیف":v===3?"قابل قبول":"مسلط")+'</span></span></div>'+
      '<p class="bd"><b>چرا لازم است:</b> '+p.why+'</p>'+
      '<p class="bd" style="color:var(--ink-2)"><b>معیار «بلدم»:</b> '+p.need+'</p>'+
      '<div style="font-size:12px;color:var(--muted);font-family:var(--mono);margin-top:6px">روز '+fa(p.day)+'</div>'+
    '</div>';
  }).join("");
  typeset($("#preCards"));
}


/* ==== src/js/quiz.js ==================================================== */

/* ---------- quiz ---------- */
function renderQuiz(qid){
  var Q = QUIZZES[qid], host = $("#"+qid);
  if(!Q||!host) return;
  var st = ST.quiz[qid] || (ST.quiz[qid]={});
  var right = Q.items.filter(function(_,i){ return st[i]===-1; }).length;
  var ans   = Q.items.filter(function(_,i){ return st[i]!==undefined && st[i]!==null; }).length;
  var head = '<div class="quiz" style="background:var(--surface-2)">'+
    '<div class="row" style="justify-content:space-between">'+
      '<b style="font-size:14px">نتیجهٔ فعلی: '+fa(right)+' از '+fa(ans)+' پاسخ‌داده'+
        ' <span style="color:var(--muted);font-weight:400">(آستانهٔ تسلط: '+fa(Q.need)+' درست)</span></b>'+
      '<button class="btn" data-qreset="'+qid+'">پاک کردن پاسخ‌ها و تلاش مجدد</button>'+
    '</div>'+
    '<div class="meter" style="margin-top:9px"><i style="width:'+Math.round(100*right/Q.items.length)+'%;background:'+
      (right>=Q.need?"var(--good)":"var(--warn)")+'"></i></div></div>';

  host.innerHTML = head + Q.items.map(function(it,i){
    var picked = st[i];
    var done = picked!==undefined && picked!==null;
    var correctIx = it.opts.findIndex(function(o){ return o.ok; });
    var opts = it.opts.map(function(o,j){
      var cls="opt";
      if(done){
        if(o.ok) cls+=" right";
        else if(picked===j) cls+=" wrong";
        else cls+=" dim";
      }
      return '<button class="'+cls+'" data-q="'+qid+'" data-i="'+i+'" data-j="'+j+'"'+(done?" disabled":"")+'>'+o.t+'</button>';
    }).join("");
    var fb="";
    if(done){
      var sel = picked===-1 ? it.opts[correctIx] : it.opts[picked];
      var good = picked===-1;
      fb = '<div class="fb '+(good?"good":"bad")+'"><span class="lbl">'+
        (good?"درست — و دلیلش:":"نادرست. خطای استدلالی شما:")+'</span>'+sel.fb+
        (good?"":'<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--line)"><b>پاسخ درست:</b> '+it.opts[correctIx].fb+'</div>')+
        '</div>';
    }
    return '<div class="quiz"><p class="q"><span class="ix">'+fa(i+1)+'.</span>'+it.q+'</p>'+opts+fb+'</div>';
  }).join("");

  host.querySelectorAll("[data-q]").forEach(function(b){
    b.addEventListener("click", function(){
      var i=+b.getAttribute("data-i"), j=+b.getAttribute("data-j");
      var ok = QUIZZES[qid].items[i].opts[j].ok;
      ST.quiz[qid][i] = ok ? -1 : j;
      save(); renderQuiz(qid); renderDash(); renderNav();
    });
  });
  var rb = host.querySelector("[data-qreset]");
  if(rb) rb.addEventListener("click", function(){
    ST.quiz[qid] = {}; save(); renderQuiz(qid); renderDash(); renderNav();
  });
  typeset(host);
}


/* ==== src/js/exercises.js =============================================== */

/* ---------- exercises ---------- */
function renderEx(key){
  var L = EXERCISES[key], host = $("#"+key);
  if(!L||!host) return;
  host.innerHTML = L.map(function(e){
    var r = ST.ex[e.id]||{};
    return '<div class="ex"><div class="hd">'+
      '<span class="id">تمرین '+e.id+'</span><span class="lvl">'+e.lvl+'</span>'+
      '<span class="st">'+
        '<button class="btn" style="padding:2px 10px;font-size:12px'+(r.st==="done"?';background:var(--good);border-color:var(--good);color:#fff':'')+'" data-exs="'+e.id+'" data-v="done">حل کردم</button>'+
        '<button class="btn" style="padding:2px 10px;font-size:12px'+(r.st==="stuck"?';background:var(--warn);border-color:var(--warn);color:#fff':'')+'" data-exs="'+e.id+'" data-v="stuck">گیر کرده‌ام</button>'+
      '</span></div>'+
      '<p class="bd">'+e.q+'</p>'+
      e.hints.map(function(h,i){
        return '<details><summary>راهنمایی '+fa(i+1)+' از '+fa(e.hints.length)+'</summary><div class="h">'+h+'</div></details>';
      }).join("")+
      '<textarea id="ta-'+e.id+'" placeholder="پاسخ، طرح اثبات، یا جایی که گیر کرده‌اید را اینجا بنویسید — ذخیره می‌شود و بعد می‌توانید در گفت‌وگو برایم بفرستید." data-exa="'+e.id+'">'+esc(r.a||"")+'</textarea>'+
    '</div>';
  }).join("");
  host.querySelectorAll("[data-exs]").forEach(function(b){
    b.addEventListener("click", function(){
      var id=b.getAttribute("data-exs"), v=b.getAttribute("data-v");
      var r = ST.ex[id] || (ST.ex[id]={});
      r.st = (r.st===v? null : v);
      save(); renderEx(key); renderDash(); renderNav();
    });
  });
  host.querySelectorAll("[data-exa]").forEach(function(t){
    var tm=null;
    t.addEventListener("input", function(){
      var id=t.getAttribute("data-exa");
      var r = ST.ex[id] || (ST.ex[id]={});
      r.a = t.value;
      clearTimeout(tm); tm=setTimeout(function(){ save(); renderDash(); }, 700);
    });
  });
  typeset(host);
}


/* ==== src/js/dep-graph.js =============================================== */

/* ---------- dependency graph ---------- */
var gSel = null;
function ancestorsOf(id){
  var pre = {}; GRAPH.edges.forEach(function(e){ (pre[e[1]]=pre[e[1]]||[]).push(e[0]); });
  var out={}, stack=[id];
  while(stack.length){
    var n=stack.pop();
    (pre[n]||[]).forEach(function(p){ if(!out[p]){ out[p]=1; stack.push(p); } });
  }
  return out;
}
function renderGraph(){
  var svg = $("#depgraph");
  var pos={}; GRAPH.nodes.forEach(function(n){ pos[n.id]=n; });
  var anc = gSel ? ancestorsOf(gSel) : null;
  var W=118, H=30;
  var eds = GRAPH.edges.map(function(e){
    var a=pos[e[0]], b=pos[e[1]];
    if(!a||!b) return "";
    var hot = anc && ((anc[e[0]]||e[0]===gSel) && (anc[e[1]]||e[1]===gSel));
    var cls = anc ? (hot?"ed hot":"ed dim") : "ed";
    var y1=a.y+H/2, y2=b.y-H/2, my=(y1+y2)/2;
    return '<path class="'+cls+'" d="M '+a.x+' '+y1+' C '+a.x+' '+my+', '+b.x+' '+my+', '+b.x+' '+y2+'"/>';
  }).join("");
  var nds = GRAPH.nodes.map(function(n){
    var st = n.t ? statusOf(n.t) : "todo";
    var cls = "nd";
    if(anc){ cls += (n.id===gSel) ? " cur" : (anc[n.id] ? " anc" : " dim"); }
    var bar = st==="mastered"?"var(--good)":st==="practice"?"var(--disc)":st==="learning"?"var(--warn)":"var(--line-2)";
    return '<g class="'+cls+'" data-nd="'+n.id+'">'+
      '<rect x="'+(n.x-W/2)+'" y="'+(n.y-H/2)+'" width="'+W+'" height="'+H+'" rx="7"/>'+
      '<rect x="'+(n.x-W/2)+'" y="'+(n.y-H/2)+'" width="4" height="'+H+'" rx="2" fill="'+bar+'" stroke="none"/>'+
      '<text x="'+n.x+'" y="'+(n.y+4)+'" text-anchor="middle">'+n.L+'</text></g>';
  }).join("");
  svg.innerHTML = eds + nds;
  svg.querySelectorAll("[data-nd]").forEach(function(g){
    g.addEventListener("click", function(){
      var id = g.getAttribute("data-nd");
      gSel = (gSel===id? null : id);
      renderGraph();
    });
  });
  var info = $("#nodeInfo");
  if(!gSel){
    info.innerHTML = '<div class="note">روی یک گره بزنید. نوار رنگی سمت راست هر گره وضعیت تسلط شما در آن مبحث است. '+
      'گره‌های بی‌نوار (امید ریاضی، فرآیند تصادفی) خارج از این دو هفته‌اند و فقط جای خود را در گراف نشان می‌دهند.</div>';
  } else {
    var n = pos[gSel], a = ancestorsOf(gSel);
    var names = Object.keys(a).map(function(k){ return pos[k]?pos[k].L:k; });
    var tp = n.t ? TOPICS.filter(function(t){return t.id===n.t;})[0] : null;
    var st = n.t ? statusOf(n.t) : null;
    info.innerHTML = '<div class="bench"><header><h4>'+n.L+'</h4>'+
      (st?'<span class="pill '+(st==="mastered"?"ok":st==="practice"?"d":st==="learning"?"mid":"")+'">'+STLAB[st]+'</span>':'<span class="tag">خارج از برنامهٔ دو هفته</span>')+
      '</header><div class="pad">'+
      (tp?'<p style="margin:0 0 9px;font-size:13.6px"><b>روز '+fa(tp.day)+'</b> · مرجع: <span class="en">'+esc(tp.ref)+'</span></p>':'')+
      '<p style="margin:0;font-size:13.6px"><b>زنجیرهٔ پیش‌نیاز ('+fa(names.length)+' گره):</b></p>'+
      '<div class="chips" style="margin-top:7px">'+(names.length?names.map(function(x){return '<button style="cursor:default">'+x+'</button>';}).join(""):'<span style="color:var(--muted);font-size:13px">این گره ریشه است و پیش‌نیازی ندارد.</span>')+'</div>'+
      '<p style="margin:11px 0 0;font-size:13px;color:var(--ink-2)">اگر در این مبحث گیر کرده‌اید، به ترتیب از بالای همین زنجیره بررسی کنید '+
      'کدام گره را واقعاً نمی‌توانید توضیح دهید. تقریباً همیشه مشکل آن‌جاست.</p>'+
      '</div></div>';
  }
}


/* ==== src/js/assignment.js ============================================== */

/* ---------- تمرین سری اول: داشبورد و میزکار هر مسئله ---------- */

/* وضعیت هر مسئله در ST.a1[id] = {read, attempt, check, sol, hint:{}, vr:{}} */
function a1State(id){
  if(!ST.a1) ST.a1 = {};
  if(!ST.a1[id]) ST.a1[id] = {hint:{}, vr:{}};
  var s = ST.a1[id];
  if(!s.hint) s.hint = {};
  if(!s.vr) s.vr = {};
  return s;
}
function a1Problem(id){
  for(var i=0;i<ASSIGNMENT.problems.length;i++)
    if(ASSIGNMENT.problems[i].id===id) return ASSIGNMENT.problems[i];
  return null;
}
/* تعداد تمرین‌های تکمیلیِ حل‌شدهٔ یک مسئله */
function a1VariantsDone(id){
  var s = a1State(id), n = 0;
  Object.keys(s.vr).forEach(function(k){ if(s.vr[k]==="done") n++; });
  return n;
}
/* قانون تسلط — سه شرط، و هیچ‌کدام «دکمه زدن» نیست:
   (۱) پاسخ درست به نقطهٔ بازبینی، (۲) ثبت حل خودِ دانشجو، (۳) دو تمرین تکمیلی. */
function a1Status(id){
  var s = a1State(id);
  var okCheck = s.check === -1;
  var okWrite = (s.attempt||"").trim().length >= 40;
  var okVar   = a1VariantsDone(id) >= 2;
  if(okCheck && okWrite && okVar) return "mastered";
  if(s.check !== undefined && s.check !== null && !okCheck) return "practice";
  if(okCheck || okWrite || a1VariantsDone(id) > 0) return "practice";
  if(s.read || s.sol) return "learning";
  return "todo";
}
function a1Pct(){
  var m = 0;
  ASSIGNMENT.problems.forEach(function(p){
    var st = a1Status(p.id);
    m += st==="mastered"?1 : st==="practice"?0.4 : st==="learning"?0.15 : 0;
  });
  return Math.round(100*m/ASSIGNMENT.problems.length);
}
function a1StatusColor(st){
  return st==="mastered"?"var(--good)" : st==="practice"?"var(--disc)"
       : st==="learning"?"var(--warn)" : "var(--line-2)";
}
var A1LAB = {todo:"شروع‌نشده", learning:"در حال کار", practice:"نیازمند تمرین بیشتر", mastered:"تسلط"};

/* ---------------- داشبورد ---------------- */
function renderA1Dash(){
  if(!$("#a1List")) return;
  var cnt = {todo:0,learning:0,practice:0,mastered:0}, vars = 0, written = 0;
  ASSIGNMENT.problems.forEach(function(p){
    cnt[a1Status(p.id)]++;
    vars += a1VariantsDone(p.id);
    if((a1State(p.id).attempt||"").trim().length >= 40) written++;
  });
  var totalVars = ASSIGNMENT.problems.reduce(function(a,p){ return a+p.variants.length; },0);

  $("#a1Kpis").innerHTML = [
    kpi("مسئله با تسلط", cnt.mastered+'<small> از '+ASSIGNMENT.problems.length+'</small>', cnt.mastered/11, ""),
    kpi("در حال کار", cnt.learning+cnt.practice, 0, null),
    kpi("حل‌های ثبت‌شدهٔ شما", written+'<small> از ۱۱</small>', written/11, ""),
    kpi("تمرین تکمیلی حل‌شده", vars+'<small> از '+totalVars+'</small>', vars/totalVars, ""),
    kpi("پیشرفت کلی تمرین", a1Pct()+'<small>٪</small>', a1Pct()/100, "")
  ].join("");

  $("#a1List").innerHTML = ASSIGNMENT.problems.map(function(p){
    var st = a1Status(p.id), s = a1State(p.id);
    var diff = ["","پایه","متوسط","دشوار","بسیار دشوار"][p.difficulty] || "";
    return '<div class="ex" style="border-inline-start:3px solid '+a1StatusColor(st)+'">'+
      '<div class="hd">'+
        '<span class="id">مسئله '+fa(p.n)+'</span>'+
        '<b style="font-size:15px">'+p.title+'</b>'+
        '<span class="lvl">'+p.kind+' · '+diff+'</span>'+
        (p.ambiguity?'<span class="pill mid">ابهام</span>':'')+
        '<span class="st">'+
          '<span class="pill '+(st==="mastered"?"ok":st==="practice"?"d":st==="learning"?"mid":"")+'">'+A1LAB[st]+'</span>'+
          '<a class="btn" style="text-decoration:none;font-size:12px;padding:3px 12px" href="#v-a1/'+p.id+'">باز کردن</a>'+
        '</span>'+
      '</div>'+
      '<p class="bd" style="color:var(--ink-2);font-size:13.6px">'+p.short+' — '+
        '<span style="color:var(--muted)">مفاهیم: '+p.concepts.join('، ')+'</span></p>'+
      '<div class="row" style="gap:6px;margin-top:7px;font-family:var(--mono);font-size:11px;color:var(--muted)">'+
        '<span>بازبینی: '+(s.check===-1?'✓ درست':(s.check!==undefined&&s.check!==null?'✗ نادرست':'—'))+'</span>'+
        '<span>·</span><span>حل ثبت‌شده: '+((s.attempt||"").trim().length>=40?'✓':'—')+'</span>'+
        '<span>·</span><span>تمرین: '+fa(a1VariantsDone(p.id))+'/'+fa(p.variants.length)+'</span>'+
        '<span>·</span><span>مبحث‌ها: '+p.topics.join(', ')+'</span>'+
      '</div></div>';
  }).join("");

  /* پوشش برنامهٔ درسی */
  var directRows = Object.keys(COVERAGE.direct).map(function(t){
    var tp = TOPICS.filter(function(x){return x.id===t;})[0];
    return '<tr><td>'+(tp?tp.name:t)+'</td>'+
      '<td class="n">'+COVERAGE.direct[t].map(function(p){return 'م'+fa(a1Problem(p).n);}).join('، ')+'</td>'+
      '<td><span class="pill c">مستقیم</span></td></tr>';
  }).join("");
  var preRows = Object.keys(COVERAGE.prerequisiteOnly).map(function(t){
    var tp = TOPICS.filter(function(x){return x.id===t;})[0];
    return '<tr><td>'+(tp?tp.name:t)+'</td><td style="font-size:12.6px;color:var(--ink-2)">'+
      COVERAGE.prerequisiteOnly[t]+'</td><td><span class="pill mid">فقط پیش‌نیاز</span></td></tr>';
  }).join("");
  $("#a1Coverage").innerHTML =
    '<div class="scrollx"><table class="tbl"><thead><tr><th>مبحث برنامهٔ درسی</th>'+
    '<th>کجا تمرین می‌شود</th><th>نوع پوشش</th></tr></thead><tbody>'+directRows+preRows+'</tbody></table></div>'+
    '<div class="warnbox" style="margin-top:14px"><span class="lbl">پوشش داده نمی‌شود</span>'+
    '<p style="margin:4px 0 8px">این‌ها هستهٔ درس فرآیندهای تصادفی‌اند و تمرین ۱ هیچ‌کدام را لمس نمی‌کند. '+
    'تکمیل این تمرین شما را «آمادهٔ فرآیندهای تصادفی» نمی‌کند؛ آماده می‌کند تا <i>بتوانید شروع کنید</i>.</p>'+
    '<div class="scrollx"><table class="tbl"><thead><tr><th>مبحث</th><th>چرا پوشش ندارد</th><th>مرجع</th></tr></thead><tbody>'+
    COVERAGE.notCovered.map(function(c){
      return '<tr><td><b>'+c.t+'</b></td><td style="font-size:12.8px">'+c.why+'</td>'+
        '<td class="n" style="font-size:11.5px">'+c.ch+'</td></tr>';
    }).join("")+'</tbody></table></div></div>';

  $("#a1Bridges").innerHTML = '<div class="scrollx"><table class="tbl">'+
    '<thead><tr><th>از مسئله</th><th>به مبحث</th><th>پل مفهومی</th></tr></thead><tbody>'+
    COVERAGE.bridges.map(function(b){
      var p = a1Problem(b.from);
      return '<tr><td class="n"><a href="#v-a1/'+b.from+'" style="color:var(--cont)">مسئله '+fa(p.n)+'</a></td>'+
        '<td><b>'+b.to+'</b></td><td style="font-size:13px">'+b.how+'</td></tr>';
    }).join("")+'</tbody></table></div>';
  typeset($("#v-a1"));
}

/* ---------------- میزکار یک مسئله ---------------- */
function a1Section(title, body, open){
  return '<details class="proof"'+(open?' open':'')+'><summary>'+title+'</summary>'+
         '<div class="body">'+body+'</div></details>';
}
function renderA1Work(id){
  var host = $("#a1Work"); if(!host) return;
  var p = a1Problem(id);
  if(!p){ host.innerHTML = '<div class="warnbox">مسئله یافت نشد.</div>'; return; }
  var s = a1State(id), st = a1Status(id);
  var ix = ASSIGNMENT.problems.indexOf(p);
  var prev = ix>0 ? ASSIGNMENT.problems[ix-1] : null;
  var next = ix<ASSIGNMENT.problems.length-1 ? ASSIGNMENT.problems[ix+1] : null;

  var h = '<div class="viewhead">'+
    '<div class="eyebrow">ASSIGNMENT 01 · مسئله '+fa(p.n)+' از ۱۱</div>'+
    '<h2>'+p.title+'</h2>'+
    '<div class="row" style="margin-top:10px">'+
      '<span class="pill '+(st==="mastered"?"ok":st==="practice"?"d":st==="learning"?"mid":"")+'">'+A1LAB[st]+'</span>'+
      '<span class="pill">'+p.kind+'</span>'+
      '<span class="pill">دشواری: '+["","پایه","متوسط","دشوار","بسیار دشوار"][p.difficulty]+'</span>'+
      (p.ambiguity?'<span class="pill mid">ابهام در صورت مسئله</span>':'')+
      '<a class="btn" style="text-decoration:none;font-size:12px" href="#v-a1">بازگشت به فهرست</a>'+
    '</div></div>';

  /* ۱ — صورت سؤال */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:28px 0 6px">صورت سؤال</h3>'+
    '<div class="def"><span class="lbl">متن اصلی — عیناً از فایل تمرین</span>'+p.statement+'</div>';

  if(p.ambiguity)
    h += '<div class="warnbox"><span class="lbl">ابهام یا فرض ناگفته</span>'+p.ambiguity+'</div>';

  /* ۲ — تحلیل مفهومی و پیش‌نیازها */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">تحلیل مفهومی</h3>'+
    '<p><b>چه چیزی سنجیده می‌شود:</b> '+p.tested+'</p>'+
    '<div class="readout">'+
      '<div><div class="k">مفاهیم درگیر</div><div style="font-size:13px;line-height:1.9">'+p.concepts.join('، ')+'</div></div>'+
      '<div><div class="k">مبحث‌های برنامهٔ درسی</div><div style="font-size:13px;line-height:1.9">'+
        p.topics.map(function(t){
          var tp = TOPICS.filter(function(x){return x.id===t;})[0];
          return tp ? '<a href="#v-map" style="color:var(--cont)">'+tp.name+'</a>' : t;
        }).join('، ')+'</div></div>'+
      '<div><div class="k">وضعیت پیش‌نیازها</div><div style="font-size:13px;line-height:1.9">'+
        p.prereqs.map(function(t){
          var tp = TOPICS.filter(function(x){return x.id===t;})[0];
          if(!tp) return '<span class="pill">'+t+'</span>';
          var ts = statusOf(t);
          return '<span class="pill '+(ts==="mastered"?"ok":ts==="practice"?"d":ts==="learning"?"mid":"no")+'">'+tp.name+'</span>';
        }).join(' ')+'</div></div>'+
    '</div>';

  /* ۳ — مبانی ریاضی */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">آموزش مبانی ریاضی</h3>'+
    p.foundation.map(function(f){ return a1Section(f.h, f.body); }).join("");

  /* ۴ — راهبرد حل */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">راهبرد حل</h3>'+
    '<p style="color:var(--ink-2);font-size:14px">این فهرست <b>پاسخ نیست</b> — نقشهٔ راه است. '+
    'قبل از باز کردن حل تشریحی، یک بار با همین راهبرد خودتان تلاش کنید.</p>'+
    '<ol class="prose">'+p.strategy.map(function(x){return '<li>'+x+'</li>';}).join("")+'</ol>';

  /* ۴٫۵ — نمایش تعاملی (فقط برای مسائلی که واقعاً از آن سود می‌برند) */
  if(typeof a1VizMarkup === "function" && a1VizMarkup(id)){
    h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">نمایش تعاملی</h3>'+
      a1VizMarkup(id);
  }

  /* ۵ — تلاش خود دانشجو */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">حل من</h3>'+
    '<div class="bench"><header><h4>دفترچهٔ شما</h4>'+
      '<span class="tag">'+((s.attempt||"").trim().length)+' نویسه — برای تسلط دست‌کم ۴۰ لازم است</span></header>'+
      '<div class="pad">'+
      '<p style="font-size:13.6px;margin:0 0 8px;color:var(--ink-2)">تلاش، طرح اثبات، یا دقیقاً جایی که '+
      'گیر کرده‌اید را بنویسید. ذخیره می‌شود و بعداً می‌توانید در گفت‌وگو برای بررسی بفرستید.</p>'+
      '<textarea id="a1ta" data-a1ta="'+id+'" style="min-height:140px">'+esc(s.attempt||"")+'</textarea>'+
      '</div></div>';

  /* ۶ — حل تشریحی، پشت دکمه */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">حل تشریحی</h3>';
  if(!s.sol){
    h += '<div class="warnbox"><span class="lbl">هنوز باز نشده</span>'+
      'پیش از باز کردن، دست‌کم یک بار با راهبرد بالا تلاش کنید و نوشته‌تان را در «حل من» ثبت کنید. '+
      'باز کردن زودهنگام، تنها فرصت یادگیری این مسئله را از بین می‌برد.'+
      '<div style="margin-top:10px"><button class="btn primary" data-a1sol="'+id+'">حل تشریحی را نشان بده</button></div></div>';
  } else {
    h += p.solution.map(function(x,i){ return a1Section('گام '+fa(i+1)+' — '+x.h, x.body, i===0); }).join("");
    h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">بررسی و اعتبارسنجی پاسخ</h3>'+
      '<div class="def"><span class="lbl">چگونه خودتان پاسخ را بیازمایید</span>'+p.verify+'</div>'+
      '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">تفسیر نتیجه</h3>'+
      '<p>'+p.interpret+'</p>'+
      '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">اشتباهات رایج</h3>'+
      '<ul class="prose">'+p.mistakes.map(function(m){return '<li>'+m+'</li>';}).join("")+'</ul>'+
      '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">الگوی قابل تعمیم</h3>'+
      '<div class="def"><span class="lbl">'+p.pattern.name+'</span>'+
        '<p style="margin:4px 0"><b>چگونه تشخیصش دهم:</b> '+p.pattern.recognize+'</p>'+
        '<p style="margin:4px 0"><b>اگر صورت مسئله عوض شود:</b> '+p.pattern.generalize+'</p></div>';
  }

  /* ۷ — نقطهٔ بازبینی */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:30px 0 6px">نقطهٔ بازبینی</h3>'+
    '<p style="color:var(--ink-2);font-size:14px">یک پرسش تشخیصی. پاسخ درست به این، یکی از سه شرط تسلط است.</p>'+
    '<div id="a1Check"></div>';

  /* ۸ — تمرین‌های تکمیلی */
  h += '<h3 style="font-family:var(--display);font-size:26px;margin:32px 0 6px">تمرین‌های تکمیلی</h3>'+
    '<p style="color:var(--ink-2);font-size:14px">چهار سؤال تازه بر پایهٔ همین مفهوم، در چهار سطح. '+
    'هیچ‌کدام صرفاً عدد عوض‌شدهٔ مسئلهٔ اصلی نیستند — هرکدام <b>جنبهٔ متفاوتی</b> را می‌سنجند. '+
    'راهنمایی‌ها پله‌پله باز می‌شوند و راه‌حل فقط با درخواست صریح.</p>'+
    '<div id="a1Vars"></div>';

  /* ناوبری */
  h += '<div class="row" style="margin-top:34px;border-top:1px solid var(--line);padding-top:16px">'+
    (prev?'<a class="btn" style="text-decoration:none" href="#v-a1/'+prev.id+'">▸ مسئله '+fa(prev.n)+'</a>':'')+
    '<a class="btn" style="text-decoration:none" href="#v-a1">فهرست مسائل</a>'+
    (next?'<a class="btn primary" style="text-decoration:none" href="#v-a1/'+next.id+'">مسئله '+fa(next.n)+' ◂</a>':'')+
    '</div>';

  host.innerHTML = h;

  /* رویدادها */
  var sol = host.querySelector("[data-a1sol]");
  if(sol) sol.addEventListener("click", function(){
    a1State(id).sol = 1; save(); renderA1Work(id); renderA1Dash(); renderNav();
  });
  var ta = host.querySelector("[data-a1ta]");
  if(ta){
    var tm = null;
    ta.addEventListener("input", function(){
      a1State(id).attempt = ta.value;
      clearTimeout(tm);
      tm = setTimeout(function(){ save(); renderA1Dash(); renderNav(); }, 700);
    });
  }
  renderA1Check(id);
  renderA1Variants(id);
  typeset(host);
  if(typeof a1VizBind === "function" && A1_VIZ[id]) setTimeout(function(){ a1VizBind(id); }, 30);
}

/* نقطهٔ بازبینی — همان موتور آزمون درس‌ها، با ذخیره در ST.a1 */
function renderA1Check(id){
  var p = a1Problem(id), s = a1State(id), host = $("#a1Check");
  if(!host || !p.check) return;
  var picked = s.check, done = picked!==undefined && picked!==null;
  var correctIx = -1;
  p.check.opts.forEach(function(o,j){ if(o.ok) correctIx = j; });
  var opts = p.check.opts.map(function(o,j){
    var cls = "opt";
    if(done){ cls += o.ok ? " right" : (picked===j ? " wrong" : " dim"); }
    return '<button class="'+cls+'" data-a1c="'+j+'"'+(done?" disabled":"")+'>'+o.t+'</button>';
  }).join("");
  var fb = "";
  if(done){
    var good = picked === -1;
    var selected = good ? p.check.opts[correctIx] : p.check.opts[picked];
    fb = '<div class="fb '+(good?"good":"bad")+'"><span class="lbl">'+
      (good?"درست — و دلیلش:":"نادرست. خطای استدلالی شما:")+'</span>'+selected.fb+
      (good?"":'<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--line)"><b>پاسخ درست:</b> '+
        p.check.opts[correctIx].fb+'</div>')+'</div>'+
      '<div style="margin-top:9px"><button class="btn" data-a1creset="1">پاک کردن و تلاش دوباره</button></div>';
  }
  host.innerHTML = '<div class="quiz"><p class="q">'+p.check.q+'</p>'+opts+fb+'</div>';
  host.querySelectorAll("[data-a1c]").forEach(function(b){
    b.addEventListener("click", function(){
      var j = +b.getAttribute("data-a1c");
      a1State(id).check = p.check.opts[j].ok ? -1 : j;
      save(); renderA1Check(id); renderA1Dash(); renderNav();
    });
  });
  var rb = host.querySelector("[data-a1creset]");
  if(rb) rb.addEventListener("click", function(){
    a1State(id).check = null; save(); renderA1Check(id); renderA1Dash(); renderNav();
  });
  typeset(host);
}

/* تمرین‌های تکمیلی با راهنمایی پله‌ای و راه‌حل پنهان */
function renderA1Variants(id){
  var p = a1Problem(id), s = a1State(id), host = $("#a1Vars");
  if(!host) return;
  var LVL = ["","۱ — پایه","۲ — متوسط","۳ — پیشرفته","۴ — چالش امتحانی ارشد"];
  var LCLS = ["","", "", "d", "mid"];
  host.innerHTML = p.variants.map(function(v, i){
    var key = p.id+"-v"+(i+1);
    var shown = s.hint[key] || 0;
    var mark = s.vr[key];
    var hints = v.hints.map(function(hh, k){
      if(k >= shown) return "";
      return '<div class="h" style="margin-top:8px"><b>راهنمایی '+fa(k+1)+':</b> '+hh+'</div>';
    }).join("");
    var more = shown < v.hints.length
      ? '<button class="btn" style="font-size:12px" data-a1h="'+key+'">'+
        (shown===0?"راهنمایی اول":"راهنمایی بعدی ("+fa(shown+1)+" از "+fa(v.hints.length)+")")+'</button>'
      : '<span class="pill">همهٔ راهنمایی‌ها باز شد</span>';
    var solBtn = s.vr[key+"-sol"]
      ? '<div class="def" style="margin-top:10px"><span class="lbl">راه‌حل و بررسی</span>'+v.verify+'</div>'
      : '<button class="btn" style="font-size:12px" data-a1vs="'+key+'">نمایش بررسی نهایی</button>';
    return '<div class="ex">'+
      '<div class="hd"><span class="id">'+p.id.toUpperCase()+'-V'+fa(i+1)+'</span>'+
        '<span class="pill '+(LCLS[v.level]||"")+'">سطح '+LVL[v.level]+'</span>'+
        '<span class="lvl">می‌سنجد: '+v.skill+'</span>'+
        '<span class="st">'+
          '<button class="btn" style="padding:2px 10px;font-size:12px'+(mark==="done"?';background:var(--good);border-color:var(--good);color:#fff':'')+'" data-a1v="'+key+'" data-v="done">حل کردم</button>'+
          '<button class="btn" style="padding:2px 10px;font-size:12px'+(mark==="stuck"?';background:var(--warn);border-color:var(--warn);color:#fff':'')+'" data-a1v="'+key+'" data-v="stuck">گیر کرده‌ام</button>'+
        '</span></div>'+
      '<p class="bd">'+v.q+'</p>'+
      '<div style="font-size:12px;color:var(--muted);font-family:var(--mono);margin-top:6px">پیش‌نیاز: '+
        v.prereqs.map(function(t){
          var tp = TOPICS.filter(function(x){return x.id===t;})[0];
          return tp?tp.name:t;
        }).join('، ')+'</div>'+
      hints+
      '<div class="row" style="margin-top:10px">'+more+solBtn+'</div>'+
    '</div>';
  }).join("");

  host.querySelectorAll("[data-a1h]").forEach(function(b){
    b.addEventListener("click", function(){
      var k = b.getAttribute("data-a1h");
      a1State(id).hint[k] = (a1State(id).hint[k]||0)+1;
      save(); renderA1Variants(id);
    });
  });
  host.querySelectorAll("[data-a1vs]").forEach(function(b){
    b.addEventListener("click", function(){
      a1State(id).vr[b.getAttribute("data-a1vs")+"-sol"] = 1;
      save(); renderA1Variants(id);
    });
  });
  host.querySelectorAll("[data-a1v]").forEach(function(b){
    b.addEventListener("click", function(){
      var k = b.getAttribute("data-a1v"), v = b.getAttribute("data-v");
      var st = a1State(id);
      st.vr[k] = (st.vr[k]===v ? null : v);
      save(); renderA1Variants(id); renderA1Dash(); renderNav();
    });
  });
  typeset(host);
}


/* ==== src/js/exam.js ==================================================== */

/* ---------- حالت آزمون: انتخاب تصادفی از بانک سؤال، تصحیح و بازخورد تشخیصی ---------- */

/* استخر سؤال‌های خودتصحیح: نقاط بازبینی یازده مسئله + آزمون‌های درس‌ها */
function examPool(){
  var pool = [];
  ASSIGNMENT.problems.forEach(function(p){
    if(p.check) pool.push({
      key:"a1:"+p.id, q:p.check.q, opts:p.check.opts,
      topics:p.topics, src:"مسئله "+fa(p.n)+" — "+p.short, level:p.difficulty
    });
  });
  Object.keys(QUIZZES).forEach(function(qid){
    QUIZZES[qid].items.forEach(function(it,i){
      pool.push({
        key:"q:"+qid+":"+i, q:it.q, opts:it.opts,
        topics:QUIZZES[qid].topics, src:(qid==="quizL1"?"درس ۱":"پرسش استاد"), level:2
      });
    });
  });
  return pool;
}
/* سؤال‌های تشریحی از بانک تمرین‌های تکمیلی */
function examOpenPool(){
  var pool = [];
  ASSIGNMENT.problems.forEach(function(p){
    p.variants.forEach(function(v,i){
      pool.push({key:p.id+"-v"+(i+1), q:v.q, verify:v.verify, hints:v.hints,
                 level:v.level, skill:v.skill, src:"مسئله "+fa(p.n), topics:p.topics});
    });
  });
  return pool;
}
function examShuffle(a, n){
  var arr = a.slice();
  for(var i=arr.length-1;i>0;i--){
    var j = Math.floor(Math.random()*(i+1));
    var t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return n ? arr.slice(0, Math.min(n, arr.length)) : arr;
}
/* ترکیب سطوح: از هر سطح دشواری سهمی برداریم تا آزمون یکنواخت نشود */
function examPick(pool, n){
  var byLevel = {}, out = [];
  pool.forEach(function(x){ (byLevel[x.level] = byLevel[x.level] || []).push(x); });
  var levels = Object.keys(byLevel).sort();
  var i = 0;
  while(out.length < n && i < 50){
    levels.forEach(function(L){
      if(out.length >= n) return;
      var bag = byLevel[L];
      if(bag && bag.length){ out.push(bag.splice(Math.floor(Math.random()*bag.length),1)[0]); }
    });
    i++;
  }
  return examShuffle(out);
}

function examState(){
  if(!ST.exam) ST.exam = {hist:[]};
  if(!ST.exam.hist) ST.exam.hist = [];
  return ST.exam;
}

function examStart(nMcq, nOpen){
  var e = examState();
  e.current = {
    mcq: examPick(examPool(), nMcq).map(function(x){ return {key:x.key, a:null}; }),
    open: examShuffle(examOpenPool(), nOpen).map(function(x){ return {key:x.key, note:"", self:null}; }),
    submitted: false,
    at: new Date().toISOString()
  };
  save(); renderExam();
}
function examFind(pool, key){
  for(var i=0;i<pool.length;i++) if(pool[i].key===key) return pool[i];
  return null;
}

function renderExam(){
  var host = $("#examHost"); if(!host) return;
  var e = examState(), cur = e.current;

  /* تاریخچه */
  var hist = "";
  if(e.hist.length){
    hist = '<h3 style="font-family:var(--display);font-size:24px;margin:30px 0 6px">عملکرد در طول زمان</h3>'+
      '<div class="scrollx"><table class="tbl"><thead><tr><th>تاریخ</th><th>نمرهٔ چندگزینه‌ای</th>'+
      '<th>خودارزیابی تشریحی</th><th>مبحث‌های ضعیف</th></tr></thead><tbody>'+
      e.hist.slice().reverse().slice(0,10).map(function(r){
        return '<tr><td class="n" style="font-size:11.5px">'+r.at.slice(0,16).replace("T"," ")+'</td>'+
          '<td class="n">'+fa(r.score)+' از '+fa(r.total)+'</td>'+
          '<td class="n">'+(r.openOk!==undefined?fa(r.openOk)+' از '+fa(r.openTotal):'—')+'</td>'+
          '<td>'+(r.weak.length? r.weak.map(function(t){
            var tp = TOPICS.filter(function(x){return x.id===t;})[0];
            return '<span class="pill no">'+(tp?tp.name:t)+'</span>';
          }).join(' ') : '<span class="pill ok">نقطهٔ ضعفی شناسایی نشد</span>')+'</td></tr>';
      }).join("")+'</tbody></table></div>';
  }

  if(!cur){
    host.innerHTML = '<div class="bench"><header><h4>شروع آزمون تازه</h4>'+
      '<span class="tag">'+fa(examPool().length)+' سؤال چندگزینه‌ای · '+fa(examOpenPool().length)+' سؤال تشریحی در بانک</span></header>'+
      '<div class="pad"><p style="font-size:14px;margin:0 0 12px">طول آزمون را انتخاب کنید. '+
      'سؤال‌ها به‌تصادف و با ترکیب سطوح دشواری انتخاب می‌شوند.</p>'+
      '<div class="row">'+
        '<button class="btn primary" data-exam="5,1">کوتاه — ۵ چندگزینه‌ای + ۱ تشریحی</button>'+
        '<button class="btn" data-exam="8,2">استاندارد — ۸ + ۲</button>'+
        '<button class="btn" data-exam="12,3">جامع — ۱۲ + ۳</button>'+
      '</div></div></div>'+hist;
    host.querySelectorAll("[data-exam]").forEach(function(b){
      b.addEventListener("click", function(){
        var p = b.getAttribute("data-exam").split(",");
        examStart(+p[0], +p[1]);
      });
    });
    typeset(host);
    return;
  }

  var pool = examPool(), openPool = examOpenPool();
  var answered = cur.mcq.filter(function(m){ return m.a !== null; }).length;
  var h = '<div class="bench"><header><h4>'+(cur.submitted?"نتیجهٔ آزمون":"آزمون در جریان")+'</h4>'+
    '<span class="tag">'+fa(answered)+' از '+fa(cur.mcq.length)+' پاسخ داده شد</span></header>'+
    '<div class="pad"><div class="meter"><i style="width:'+Math.round(100*answered/cur.mcq.length)+'%"></i></div>'+
    '<div class="row" style="margin-top:12px">'+
      (cur.submitted
        ? '<button class="btn primary" data-examnew="1">آزمون تازه</button>'
        : '<button class="btn primary" data-examsubmit="1"'+(answered<cur.mcq.length?' disabled':'')+'>ثبت و تصحیح</button>'+
          '<button class="btn" data-examabort="1">انصراف</button>'+
          '<span style="font-size:12.6px;color:var(--muted)">تا پیش از ثبت، هیچ پاسخی نمایش داده نمی‌شود.</span>')+
    '</div></div></div>';

  /* بخش الف — چندگزینه‌ای */
  h += '<h3 style="font-family:var(--display);font-size:24px;margin:28px 0 6px">بخش الف — چندگزینه‌ای</h3>';
  cur.mcq.forEach(function(m, i){
    var item = examFind(pool, m.key);
    if(!item){ h += ''; return; }
    var correctIx = -1;
    item.opts.forEach(function(o,j){ if(o.ok) correctIx = j; });
    var opts = item.opts.map(function(o,j){
      var cls = "opt";
      if(cur.submitted){ cls += o.ok ? " right" : (m.a===j ? " wrong" : " dim"); }
      else if(m.a===j){ cls += " right"; }
      return '<button class="'+cls+'" data-em="'+i+'" data-ej="'+j+'"'+(cur.submitted?" disabled":"")+'>'+o.t+'</button>';
    }).join("");
    var fb = "";
    if(cur.submitted){
      var ok = m.a === correctIx;
      fb = '<div class="fb '+(ok?"good":"bad")+'"><span class="lbl">'+(ok?"درست":"نادرست")+'</span>'+
        item.opts[m.a!==null?m.a:correctIx].fb+
        (ok?"":'<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--line)"><b>پاسخ درست:</b> '+
          item.opts[correctIx].fb+'</div>')+'</div>';
    }
    h += '<div class="quiz"><p class="q"><span class="ix">'+fa(i+1)+'.</span>'+item.q+
      '<span class="pill" style="margin-inline-start:8px">'+item.src+'</span></p>'+opts+fb+'</div>';
  });

  /* بخش ب — تشریحی */
  if(cur.open.length){
    h += '<h3 style="font-family:var(--display);font-size:24px;margin:30px 0 6px">بخش ب — تشریحی</h3>'+
      '<p style="color:var(--ink-2);font-size:13.8px">این‌ها خودتصحیح نیستند. پاسخ خود را بنویسید؛ '+
      'پس از ثبت، معیار بررسی نمایش داده می‌شود و خودتان داوری می‌کنید.</p>';
    cur.open.forEach(function(o, i){
      var item = examFind(openPool, o.key);
      if(!item) return;
      h += '<div class="ex"><div class="hd"><span class="id">'+item.key.toUpperCase()+'</span>'+
        '<span class="pill '+(item.level>=4?"mid":item.level>=3?"d":"")+'">سطح '+fa(item.level)+'</span>'+
        '<span class="lvl">'+item.src+' · '+item.skill+'</span></div>'+
        '<p class="bd">'+item.q+'</p>'+
        '<textarea data-eo="'+i+'" placeholder="پاسخ خود را اینجا بنویسید…">'+esc(o.note||"")+'</textarea>';
      if(cur.submitted){
        h += '<div class="def" style="margin-top:10px"><span class="lbl">معیار بررسی</span>'+item.verify+'</div>'+
          '<div class="row" style="margin-top:9px"><span style="font-size:13px">خودارزیابی:</span>'+
          '<button class="btn" style="font-size:12px'+(o.self==="ok"?';background:var(--good);border-color:var(--good);color:#fff':'')+'" data-es="'+i+'" data-v="ok">درست حل کردم</button>'+
          '<button class="btn" style="font-size:12px'+(o.self==="partial"?';background:var(--warn);border-color:var(--warn);color:#fff':'')+'" data-es="'+i+'" data-v="partial">نیمه‌درست</button>'+
          '<button class="btn" style="font-size:12px'+(o.self==="no"?';background:var(--bad);border-color:var(--bad);color:#fff':'')+'" data-es="'+i+'" data-v="no">نتوانستم</button></div>';
      }
      h += '</div>';
    });
  }

  /* خلاصهٔ تشخیصی */
  if(cur.submitted){
    var score = 0, weak = {};
    cur.mcq.forEach(function(m){
      var item = examFind(pool, m.key); if(!item) return;
      var ok = item.opts[m.a] && item.opts[m.a].ok;
      if(ok) score++; else item.topics.forEach(function(t){ weak[t] = (weak[t]||0)+1; });
    });
    var weakList = Object.keys(weak).sort(function(a,b){ return weak[b]-weak[a]; });
    h += '<h3 style="font-family:var(--display);font-size:24px;margin:30px 0 6px">بازخورد تشخیصی</h3>'+
      '<div class="kpis">'+
        kpi("نمرهٔ چندگزینه‌ای", score+'<small> از '+cur.mcq.length+'</small>', score/cur.mcq.length, "")+
        kpi("درصد", Math.round(100*score/cur.mcq.length)+'<small>٪</small>', score/cur.mcq.length, "")+
      '</div>';
    if(weakList.length){
      h += '<div class="warnbox"><span class="lbl">مبحث‌هایی که باید به آن‌ها برگردید</span>'+
        '<p style="margin:4px 0 8px">این‌ها از روی پاسخ‌های نادرست شما استخراج شده‌اند. '+
        'به ترتیب اولویت:</p><div class="row">'+
        weakList.map(function(t){
          var tp = TOPICS.filter(function(x){return x.id===t;})[0];
          var view = tp && tp.view ? tp.view : "v-map";
          return '<a class="btn" style="text-decoration:none;font-size:12.5px" href="#'+view+'">'+
            (tp?tp.name:t)+' <span style="color:var(--muted)">('+fa(weak[t])+' خطا)</span></a>';
        }).join("")+'</div></div>';
    } else {
      h += '<div class="note"><span class="lbl">بدون نقطهٔ ضعف</span>همهٔ سؤال‌های چندگزینه‌ای درست پاسخ داده شد. '+
        'آزمون جامع‌تری بگیرید تا سؤال‌های سطح بالاتر هم بیایند.</div>';
    }
  }

  h += hist;
  host.innerHTML = h;

  /* رویدادها */
  host.querySelectorAll("[data-em]").forEach(function(b){
    b.addEventListener("click", function(){
      var i = +b.getAttribute("data-em"), j = +b.getAttribute("data-ej");
      examState().current.mcq[i].a = j;
      save(); renderExam();
    });
  });
  host.querySelectorAll("[data-eo]").forEach(function(t){
    var tm = null;
    t.addEventListener("input", function(){
      examState().current.open[+t.getAttribute("data-eo")].note = t.value;
      clearTimeout(tm); tm = setTimeout(save, 700);
    });
  });
  host.querySelectorAll("[data-es]").forEach(function(b){
    b.addEventListener("click", function(){
      var i = +b.getAttribute("data-es"), v = b.getAttribute("data-v");
      var o = examState().current.open[i];
      o.self = (o.self===v ? null : v);
      save(); renderExam();
    });
  });
  var sb = host.querySelector("[data-examsubmit]");
  if(sb) sb.addEventListener("click", function(){
    var e2 = examState(), c = e2.current, pl = examPool();
    var score = 0, weak = {};
    c.mcq.forEach(function(m){
      var item = examFind(pl, m.key); if(!item) return;
      if(item.opts[m.a] && item.opts[m.a].ok) score++;
      else item.topics.forEach(function(t){ weak[t] = (weak[t]||0)+1; });
    });
    c.submitted = true;
    e2.hist.push({at:c.at, score:score, total:c.mcq.length,
                  weak:Object.keys(weak), openTotal:c.open.length, openOk:0});
    save(); renderExam();
  });
  var ab = host.querySelector("[data-examabort]");
  if(ab) ab.addEventListener("click", function(){
    examState().current = null; save(); renderExam();
  });
  var nb = host.querySelector("[data-examnew]");
  if(nb) nb.addEventListener("click", function(){
    examState().current = null; save(); renderExam();
  });
  typeset(host);
}


/* ==== src/js/main.js ==================================================== */

/* ---------- boot ---------- */
/* مسیریابی: "#v-a1/p3" یعنی نمای میزکار با پارامتر p3.
   نماهای قدیمی ("#v-l1") بدون تغییر کار می‌کنند. */
function hashParts(){
  var raw = (location.hash || "").replace(/^#/, "");
  if(!raw) return {view:"v-dash", param:null};
  var bits = raw.split("/");
  return {view:bits[0] || "v-dash", param:bits[1] || null};
}
function viewIdFromHash(){
  var hp = hashParts();
  if(hp.view === "v-a1" && hp.param) return "v-a1w";
  return hp.view;
}
function renderAll(){
  renderNav(); renderDash(); renderRoad(); renderThm(); renderPre(); renderGraph();
  renderQuiz("quizL1"); renderQuiz("quizQ");
  renderEx("exL1"); renderEx("exQ");
  renderA1Dash(); renderExam();
  var hp = hashParts();
  if(hp.view === "v-a1" && hp.param) renderA1Work(hp.param);
}
function redrawVisible(){
  var v = viewIdFromHash();
  if(typeof drawExp!=="function") return;
  if(v==="v-l1"){ drawExp(); renderVenn(); }
  if(v==="v-q"){ drawCdf(); }
  if(v==="v-a1w" && typeof drawPoisson==="function") drawA1Instruments(hashParts().param);
}
/* کدام مباحث با باز کردن یک درس «در حال یادگیری» می‌شوند.
   خواندن هرگز به «تسلط» نمی‌رسد — آن فقط از آزمون و تمرین می‌آید. */
var READ_ON_VIEW = { "#v-l1":["exp","event","sigma"], "#v-q":["cdf"] };
function markViewRead(hash){
  var ids = READ_ON_VIEW[hash];
  if(!ids) return false;
  var changed = false;
  ids.forEach(function(id){ if(!ST.read[id]){ ST.read[id]=1; changed=true; } });
  if(changed) save();
  return changed;
}
window.addEventListener("hashchange", function(){
  if(markViewRead("#"+hashParts().view)) renderDash();
  var hp = hashParts();
  if(hp.view === "v-a1" && hp.param){
    a1State(hp.param).read = 1; save();
    renderA1Work(hp.param);
  }
  renderNav();
  try{ window.scrollTo(0,0); }catch(e){}
  setTimeout(redrawVisible, 20);
});
document.documentElement.dir = "rtl";
document.documentElement.lang = "fa";
$("#themeBtn").addEventListener("click", function(){
  var r=document.documentElement, cur=r.getAttribute("data-theme");
  var sysDark = window.matchMedia && window.matchMedia("(prefers-color-scheme:dark)").matches;
  var next = cur ? (cur==="dark"?"light":"dark") : (sysDark?"light":"dark");
  r.setAttribute("data-theme", next);
  try{ localStorage.setItem(LSKEY+"-theme", next); }catch(e){}
});
try{ var th=localStorage.getItem(LSKEY+"-theme"); if(th) document.documentElement.setAttribute("data-theme",th); }catch(e){}
$("#resetBtn").addEventListener("click", function(){
  if(!confirm("کل پیشرفت، پاسخ آزمون‌ها و متن تمرین‌ها پاک می‌شود. مطمئنید؟")) return;
  ST = {topics:{},quiz:{},ex:{},pre:{},thm:{},read:{},a1:{},exam:{}};
  try{ localStorage.removeItem(LSKEY); }catch(e){}
  if(dbRef) dbRef.set({state:ST, at:new Date().toISOString()}).catch(function(){});
  renderAll();
});
/* ترتیب مهم است: اول پیشرفتِ ذخیره‌شده را بخوان، بعد رندر کن.
   اگر برعکس باشد، هر بار بارگذاری مجدد داشبورد خالی نشان می‌دهد. */
loadLocal();
markViewRead("#"+hashParts().view);
if(hashParts().view==="v-a1" && hashParts().param) a1State(hashParts().param).read = 1;
renderAll();
setTimeout(redrawVisible, 50);
initPersistence();
if(window.MathJax && MathJax.startup && MathJax.startup.promise){
  MathJax.startup.promise.then(function(){ typeset(); });
}


/* ==== src/js/instruments/canvas.js ====================================== */

/* اندازه‌گیری canvas با devicePixelRatio و خواندن توکن‌های رنگ تم */
function cv(id, h){
  var c = $("#"+id), wrap = c.parentNode;
  var w = Math.max(300, wrap.clientWidth||600);
  var dpr = window.devicePixelRatio||1;
  c.width = Math.round(w*dpr); c.height = Math.round(h*dpr);
  c.style.width = w+"px"; c.style.height = h+"px";
  var g = c.getContext("2d"); g.setTransform(dpr,0,0,dpr,0,0);
  g.clearRect(0,0,w,h);
  return {g:g, w:w, h:h};
}
function tok(n){ return getComputedStyle(document.documentElement).getPropertyValue(n).trim(); }


/* ==== src/js/instruments/experiment.js ================================== */

function bits(n){
  var out=[]; for(var i=0;i<(1<<n);i++){ var s=""; for(var k=n-1;k>=0;k--) s+= (i>>k)&1; out.push(s); }
  return out;
}
var EXPS = {
  coin1:{ nm:"یک سکه", out:["ش","خ"], grid:0,
    note:"$S=\\{\\text{ش},\\text{خ}\\}$ — سکهٔ سالم، دو برون‌داد هم‌احتمال." },
  coin2:{ nm:"دو سکه", out:["شش","شخ","خش","خخ"], grid:0,
    note:"$S=\\{\\text{شش},\\text{شخ},\\text{خش},\\text{خخ}\\}$ — <b>ترتیب‌دار</b>، چهار برون‌داد هم‌احتمال. دقت کنید «شخ» و «خش» دو برون‌داد <b>متفاوت</b>اند.",
    pre:[{l:"دقیقاً یک شیر",f:function(o){return o==="شخ"||o==="خش";}},
         {l:"حداقل یک شیر",f:function(o){return o.indexOf("ش")>=0;}}] },
  die1:{ nm:"یک تاس", out:["1","2","3","4","5","6"], grid:0,
    note:"$S=\\{1,\\dots,6\\}$ — تاس سالم، شش برون‌داد هم‌احتمال.",
    pre:[{l:"زوج",f:function(o){return (+o)%2===0;}},{l:"بزرگ‌تر از ۴",f:function(o){return (+o)>4;}}] },
  die2:{ nm:"دو تاس", out:(function(){var a=[];for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)a.push(i+","+j);return a;})(), grid:1,
    note:"$S=\\{(i,j): 1\\le i,j\\le 6\\}$ — $|S|=36$ برون‌داد هم‌احتمال. جدول را مثل ماتریس بخوانید: سطر = تاس اول.",
    pre:[{l:"مجموع = ۷",f:function(o){var p=o.split(",");return +p[0]+ +p[1]===7;}},
         {l:"مجموع ≥ ۱۰",f:function(o){var p=o.split(",");return +p[0]+ +p[1]>=10;}},
         {l:"هر دو زوج",f:function(o){var p=o.split(",");return p[0]%2===0&&p[1]%2===0;}},
         {l:"حداقل یک ۶",f:function(o){return o.indexOf("6")>=0;}}] },
  bsc3:{ nm:"سه بیت روی BSC (p=0.2)", out:bits(3), grid:0,
    probs:(function(){ var p=0.2; return bits(3).map(function(s){
      var w=0; for(var i=0;i<3;i++) if(s[i]==="1") w++;
      return Math.pow(p,w)*Math.pow(1-p,3-w); }); })(),
    note:"$S=\\{0,1\\}^3$ با ۱ = «بیت خطا دارد». این برون‌دادها <b>هم‌احتمال نیستند</b>: هر بیت با احتمال $p=0.2$ مستقل خطا می‌کند، پس $P(\\zeta)=p^{w}(1-p)^{3-w}$ که $w$ تعداد یک‌هاست. اینجا فرمول $|A|/|S|$ <b>غلط</b> است — همین را در نمودار ببینید.",
    pre:[{l:"حداقل دو خطا",f:function(o){return (o.match(/1/g)||[]).length>=2;}},
         {l:"بدون خطا",f:function(o){return o==="000";}},
         {l:"دقیقاً یک خطا",f:function(o){return (o.match(/1/g)||[]).length===1;}}] }
};
var EX = { key:"coin2", A:{}, n:0, nA:0, hist:[] };

function exProbs(){
  var e = EXPS[EX.key];
  if(e.probs) return e.probs;
  return e.out.map(function(){ return 1/e.out.length; });
}
function exPA(){
  var p = exProbs(), e = EXPS[EX.key], s=0;
  e.out.forEach(function(o,i){ if(EX.A[o]) s += p[i]; });
  return s;
}
function exPick(){
  var p = exProbs(), r = Math.random(), c = 0;
  for(var i=0;i<p.length;i++){ c += p[i]; if(r < c) return i; }
  return p.length-1;
}
function exShouldRecord(n){
  if(n<=60) return true;
  if(n<=600) return n%5===0;
  if(n<=6000) return n%50===0;
  return n%500===0;
}
function exRun(k){
  var e = EXPS[EX.key];
  for(var i=0;i<k;i++){
    var ix = exPick();
    EX.n++;
    if(EX.A[e.out[ix]]) EX.nA++;
    if(exShouldRecord(EX.n)) EX.hist.push([EX.n, EX.nA/EX.n]);
  }
  if(EX.hist.length===0 || EX.hist[EX.hist.length-1][0]!==EX.n) EX.hist.push([EX.n, EX.nA/EX.n]);
  drawExp(); fillExpReadout();
}
function renderExp(){
  var e = EXPS[EX.key];
  $("#expPicker").innerHTML = Object.keys(EXPS).map(function(k){
    return '<button class="btn '+(k===EX.key?"sel":"")+'" data-exp="'+k+'">'+EXPS[k].nm+'</button>';
  }).join("");
  $("#expPicker").querySelectorAll("[data-exp]").forEach(function(b){
    b.addEventListener("click", function(){
      EX.key = b.getAttribute("data-exp"); EX.A={}; EX.n=0; EX.nA=0; EX.hist=[];
      renderExp();
    });
  });
  $("#expOutcomes").innerHTML = '<div class="chips'+(e.grid?" grid6":"")+'">'+
    e.out.map(function(o){ return '<button class="'+(EX.A[o]?"in":"")+'" data-out="'+o+'">'+o+'</button>'; }).join("")+'</div>';
  $("#expOutcomes").querySelectorAll("[data-out]").forEach(function(b){
    b.addEventListener("click", function(){
      var o=b.getAttribute("data-out");
      if(EX.A[o]) delete EX.A[o]; else EX.A[o]=1;
      EX.n=0; EX.nA=0; EX.hist=[]; renderExp();
    });
  });
  $("#expPresets").innerHTML = (e.pre||[]).map(function(p,i){
    return '<button class="btn" style="font-size:12px" data-pre="'+i+'">'+p.l+'</button>';
  }).join("") + (e.pre? '<button class="btn" style="font-size:12px" data-pre="-1">پاک کردن A</button>':'');
  $("#expPresets").querySelectorAll("[data-pre]").forEach(function(b){
    b.addEventListener("click", function(){
      var i=+b.getAttribute("data-pre");
      EX.A={};
      if(i>=0) e.out.forEach(function(o){ if(e.pre[i].f(o)) EX.A[o]=1; });
      EX.n=0; EX.nA=0; EX.hist=[]; renderExp();
    });
  });
  var sel = e.out.filter(function(o){ return EX.A[o]; });
  var uni = !e.probs;
  $("#expSetNote").innerHTML = e.note + '<br><br>'+
    '<b>پیشامد انتخابی:</b> ' + (sel.length? '$A=\\{'+sel.map(function(s){return "\\text{"+s+"}";}).join(",\\,")+'\\}$' : '$A=\\varnothing$') +
    ' &nbsp;·&nbsp; $|A|='+sel.length+'$، $|S|='+e.out.length+'$'+
    (uni ? ' &nbsp;·&nbsp; چون برون‌دادها هم‌احتمال‌اند، $P(A)=|A|/|S|$ معتبر است.'
         : ' &nbsp;·&nbsp; <b style="color:var(--warn)">برون‌دادها هم‌احتمال نیستند</b>، پس $|A|/|S|='+
           (sel.length/e.out.length).toFixed(4)+'$ در حالی که $P(A)='+exPA().toFixed(4)+'$.');
  typeset($("#expSetNote"));
  drawExp(); fillExpReadout();
}
function fillExpReadout(){
  var pA = exPA(), ph = EX.n? EX.nA/EX.n : NaN;
  $("#expReadout").innerHTML = [
    ro("$P(A)$ نظری", pA.toFixed(4)),
    ro("تعداد اجرا&nbsp; n", fa(EX.n)),
    ro("وقوع A&nbsp; n<sub>A</sub>", fa(EX.nA)),
    ro("فراوانی نسبی", EX.n? ph.toFixed(4):"—"),
    ro("قطر خطا", EX.n? Math.abs(ph-pA).toFixed(4):"—"),
    ro("کرانهٔ ۲σ", EX.n? (2*Math.sqrt(Math.max(pA*(1-pA),0)/EX.n)).toFixed(4):"—")
  ].join("");
  typeset($("#expReadout"));
}
function ro(k,v){ return '<div><div class="k">'+k+'</div><div class="n">'+v+'</div></div>'; }


function drawExp(){
  var o = cv("expChart", 230), g=o.g, W=o.w, H=o.h;
  var L=46, R=12, T=14, B=30, pw=W-L-R, ph=H-T-B;
  var ink=tok("--ink"), mut=tok("--muted"), line=tok("--line"), cont=tok("--cont"), disc=tok("--disc");
  var pA = exPA();
  var nmax = Math.max(100, EX.n);
  function X(n){ return L + pw * (Math.log10(Math.max(1,n))/Math.log10(nmax)); }
  function Y(p){ return T + ph * (1-p); }

  // 2 sigma band
  if(pA>0 && pA<1){
    g.fillStyle = cont; g.globalAlpha = 0.12; g.beginPath();
    var first=true;
    for(var n=1;n<=nmax;n*=1.06){
      var s = 2*Math.sqrt(pA*(1-pA)/n);
      var y = Y(Math.min(1,pA+s));
      if(first){ g.moveTo(X(n),y); first=false; } else g.lineTo(X(n),y);
    }
    for(var n2=nmax;n2>=1;n2/=1.06){
      var s2 = 2*Math.sqrt(pA*(1-pA)/n2);
      g.lineTo(X(n2), Y(Math.max(0,pA-s2)));
    }
    g.closePath(); g.fill(); g.globalAlpha=1;
  }
  // grid
  g.strokeStyle=line; g.lineWidth=1; g.font="11px "+(tok("--mono")||"monospace"); g.fillStyle=mut;
  [0,0.25,0.5,0.75,1].forEach(function(p){
    g.beginPath(); g.moveTo(L,Y(p)); g.lineTo(W-R,Y(p)); g.stroke();
    g.textAlign="right"; g.textBaseline="middle"; g.fillText(p.toFixed(2), L-7, Y(p));
  });
  var decades=[1,10,100,1000,10000,100000].filter(function(d){ return d<=nmax; });
  g.textAlign="center"; g.textBaseline="top";
  decades.forEach(function(d){
    g.strokeStyle=line; g.beginPath(); g.moveTo(X(d),T); g.lineTo(X(d),T+ph); g.stroke();
    g.fillStyle=mut; g.fillText(String(d), X(d), T+ph+7);
  });
  // theoretical P(A)
  g.strokeStyle=cont; g.lineWidth=1.8; g.setLineDash([6,4]);
  g.beginPath(); g.moveTo(L,Y(pA)); g.lineTo(W-R,Y(pA)); g.stroke(); g.setLineDash([]);
  g.fillStyle=cont; g.textAlign="left"; g.textBaseline="bottom";
  g.fillText("P(A) = "+pA.toFixed(3), L+5, Y(pA)-3);
  // trajectory
  if(EX.hist.length){
    g.strokeStyle=disc; g.lineWidth=1.7; g.beginPath();
    EX.hist.forEach(function(p,i){ var x=X(p[0]), y=Y(p[1]); if(i===0)g.moveTo(x,y); else g.lineTo(x,y); });
    g.stroke();
    var last=EX.hist[EX.hist.length-1];
    g.fillStyle=disc; g.beginPath(); g.arc(X(last[0]),Y(last[1]),3.5,0,6.284); g.fill();
  } else {
    g.fillStyle=mut; g.textAlign="center"; g.textBaseline="middle";
    g.font="13px "+(tok("--body")||"sans-serif");
    g.fillText("برای دیدن مسیر فراوانی نسبی، آزمایش را اجرا کنید", L+pw/2, T+ph/2);
  }
  g.strokeStyle=tok("--line-2"); g.lineWidth=1;
  g.beginPath(); g.moveTo(L,T); g.lineTo(L,T+ph); g.lineTo(W-R,T+ph); g.stroke();
}


/* ==== src/js/instruments/venn.js ======================================== */

/* ============================================================
   میزکار ۲ — دیاگرام ون و نوار دقیق
   ============================================================ */
var VOPS = [
  {k:"union",  l:"A ∪ B",   r:["ao","ab","bo"], tex:"A\\cup B", say:"«$A$ یا $B$»"},
  {k:"inter",  l:"A ∩ B",   r:["ab"],           tex:"A\\cap B", say:"«$A$ و $B$»"},
  {k:"cA",     l:"Ā",       r:["bo","out"],     tex:"\\bar A", say:"«$A$ رخ نداد»"},
  {k:"cB",     l:"B̄",       r:["ao","out"],     tex:"\\bar B", say:"«$B$ رخ نداد»"},
  {k:"diff",   l:"A − B",   r:["ao"],           tex:"A-B=A\\cap\\bar B", say:"«$A$ ولی نه $B$»"},
  {k:"symm",   l:"A △ B",   r:["ao","bo"],      tex:"A\\triangle B", say:"«دقیقاً یکی از دو»"},
  {k:"ncup",   l:"(A∪B)‾",  r:["out"],          tex:"\\overline{A\\cup B}", say:"«هیچ‌کدام»"},
  {k:"dm",     l:"Ā ∩ B̄",   r:["out"],          tex:"\\bar A\\cap\\bar B", say:"«نه $A$ و نه $B$» — دمورگان: با گزینهٔ قبلی یکی است"},
  {k:"S",      l:"S",       r:["ao","ab","bo","out"], tex:"S", say:"پیشامد حتمی"}
];
var V = {op:"union", a:0.5, b:0.4, c:0.2};
function vClamp(){
  var lo = Math.max(0, V.a+V.b-1), hi = Math.min(V.a, V.b);
  V.c = Math.min(hi, Math.max(lo, V.c));
}
function vProbs(){ return {ao:V.a-V.c, ab:V.c, bo:V.b-V.c, out:1-V.a-V.b+V.c}; }
function renderVenn(){
  $("#vennOps").innerHTML = VOPS.map(function(o){
    return '<button class="btn '+(o.k===V.op?"sel":"")+'" style="font-family:var(--mono);font-size:12.5px" data-vop="'+o.k+'">'+o.l+'</button>';
  }).join("");
  $("#vennOps").querySelectorAll("[data-vop]").forEach(function(b){
    b.addEventListener("click", function(){ V.op=b.getAttribute("data-vop"); renderVenn(); });
  });
  var op = VOPS.filter(function(o){return o.k===V.op;})[0];

  // --- schematic Venn (SVG) ---
  var ax=160, bx=252, cy=125, r=76;
  var on = {}; op.r.forEach(function(k){ on[k]=1; });
  var cont=tok("--cont"), disc=tok("--disc"), line=tok("--line-2"), surf=tok("--surface-2"), ink=tok("--ink");
  var svg = '<defs>'+
    '<clipPath id="clipA"><circle cx="'+ax+'" cy="'+cy+'" r="'+r+'"/></clipPath>'+
    '<clipPath id="clipB"><circle cx="'+bx+'" cy="'+cy+'" r="'+r+'"/></clipPath>'+
    '<mask id="notB"><rect x="0" y="0" width="420" height="250" fill="#fff"/><circle cx="'+bx+'" cy="'+cy+'" r="'+r+'" fill="#000"/></mask>'+
    '<mask id="notA"><rect x="0" y="0" width="420" height="250" fill="#fff"/><circle cx="'+ax+'" cy="'+cy+'" r="'+r+'" fill="#000"/></mask>'+
    '<mask id="notAB"><rect x="0" y="0" width="420" height="250" fill="#fff"/>'+
      '<circle cx="'+ax+'" cy="'+cy+'" r="'+r+'" fill="#000"/><circle cx="'+bx+'" cy="'+cy+'" r="'+r+'" fill="#000"/></mask>'+
    '</defs>'+
    '<rect x="8" y="8" width="404" height="234" rx="9" fill="'+surf+'" stroke="'+line+'"/>'+
    (on.out? '<rect x="8" y="8" width="404" height="234" rx="9" fill="'+cont+'" opacity="0.30" mask="url(#notAB)"/>':'')+
    (on.ao? '<circle cx="'+ax+'" cy="'+cy+'" r="'+r+'" fill="'+cont+'" opacity="0.42" mask="url(#notB)"/>':'')+
    (on.bo? '<circle cx="'+bx+'" cy="'+cy+'" r="'+r+'" fill="'+cont+'" opacity="0.42" mask="url(#notA)"/>':'')+
    (on.ab? '<g clip-path="url(#clipB)"><circle cx="'+ax+'" cy="'+cy+'" r="'+r+'" fill="'+disc+'" opacity="0.55"/></g>':'')+
    '<circle cx="'+ax+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+ink+'" stroke-width="1.5"/>'+
    '<circle cx="'+bx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+ink+'" stroke-width="1.5"/>'+
    '<text x="104" y="52" fill="'+ink+'" font-size="15">A</text>'+
    '<text x="306" y="52" fill="'+ink+'" font-size="15">B</text>'+
    '<text x="24" y="30" fill="'+tok("--muted")+'" font-size="13">S</text>';
  $("#vennSvg").innerHTML = svg;
  $("#vennExpr").innerHTML = '<b style="font-family:var(--mono)">$'+op.tex+'$</b> &nbsp;—&nbsp; '+op.say+
    ' <span style="color:var(--muted);font-size:12.6px">· شکل بالا شماتیک است؛ مساحت‌ها متناسب با احتمال نیستند. نوار پایین دقیق است.</span>';
  typeset($("#vennExpr"));

  // --- exact bar ---
  vClamp();
  $("#vPA").value=V.a; $("#vPB").value=V.b; $("#vPAB").value=V.c;
  $("#vPAv").textContent=V.a.toFixed(2); $("#vPBv").textContent=V.b.toFixed(2); $("#vPABv").textContent=V.c.toFixed(2);
  var p=vProbs(), BW=600, X0=20, BY=30, BH=40;
  function seg(x,w,fill,op2){ return w<=1e-9?"":'<rect x="'+(X0+x*BW)+'" y="'+BY+'" width="'+(w*BW)+'" height="'+BH+'" fill="'+fill+'" opacity="'+op2+'"/>'; }
  var base = tok("--surface-2"), g2="";
  g2 += '<rect x="'+X0+'" y="'+BY+'" width="'+BW+'" height="'+BH+'" fill="'+base+'" stroke="'+line+'"/>';
  g2 += seg(0, p.ao, on.ao?cont:base, on.ao?0.5:1);
  g2 += seg(p.ao, p.ab, on.ab?disc:base, on.ab?0.65:1);
  g2 += seg(p.ao+p.ab, p.bo, on.bo?cont:base, on.bo?0.5:1);
  g2 += seg(p.ao+p.ab+p.bo, p.out, on.out?cont:base, on.out?0.3:1);
  // boundary ticks for A and B extents
  [[0,V.a,"A",cont],[p.ao,p.ao+V.b,"B",disc]].forEach(function(t,i){
    var y = BY-10-i*0;
    g2 += '<line x1="'+(X0+t[0]*BW)+'" y1="'+(BY+BH+6+i*16)+'" x2="'+(X0+t[1]*BW)+'" y2="'+(BY+BH+6+i*16)+
          '" stroke="'+t[3]+'" stroke-width="3"/>'+
          '<text x="'+(X0+((t[0]+t[1])/2)*BW)+'" y="'+(BY+BH+4+i*16)+'" fill="'+t[3]+
          '" font-size="11" text-anchor="middle">'+t[2]+'</text>';
  });
  g2 += '<text x="'+X0+'" y="'+(BY-8)+'" fill="'+tok("--muted")+'" font-size="11">0</text>'+
        '<text x="'+(X0+BW)+'" y="'+(BY-8)+'" fill="'+tok("--muted")+'" font-family="'+(tok("--mono")||"monospace")+
        '" font-size="11" text-anchor="end">1</text>';
  $("#barSvg").innerHTML = g2;

  var sel = op.r.reduce(function(s,k){ return s+p[k]; },0);
  $("#vennReadout").innerHTML = [
    ro("$P(\\text{ناحیهٔ انتخابی})$", sel.toFixed(3)),
    ro("$P(A\\cap\\bar B)$", p.ao.toFixed(3)),
    ro("$P(A\\cap B)$", p.ab.toFixed(3)),
    ro("$P(\\bar A\\cap B)$", p.bo.toFixed(3)),
    ro("$P(\\bar A\\cap\\bar B)$", p.out.toFixed(3)),
    ro("$P(A)P(B)$", (V.a*V.b).toFixed(3))
  ].join("");
  typeset($("#vennReadout"));

  var indep = Math.abs(V.c - V.a*V.b) < 5e-3;
  var excl  = V.c < 1e-9;
  var pos   = V.a>1e-9 && V.b>1e-9;
  var parts = [];
  parts.push(excl? '<span class="pill ok">ناسازگار ✓</span>' : '<span class="pill">ناسازگار ✗</span>');
  parts.push(indep? '<span class="pill ok">مستقل ✓</span>' : '<span class="pill">مستقل ✗</span>');
  var msg;
  if(excl && pos) msg = 'هر دو احتمال مثبت‌اند و $P(A\\cap B)=0$. پس $P(A\\cap B)=0 \\ne P(A)P(B)='+(V.a*V.b).toFixed(3)+
    '$ — <b>ناسازگاری در اینجا شدیدترین نوع وابستگی است</b>، نه بی‌ربطی. دقیقاً همان تمایزی که جلسهٔ اول مطرح شد.';
  else if(excl && !pos) msg = 'یکی از احتمال‌ها صفر است. در این حالت مرزی، پیشامدها هم ناسازگارند و هم (به‌طور بدیهی) مستقل — '+
    'چون هر دو طرف تعریف استقلال صفر می‌شوند. این تنها حالتی است که ناسازگاری و استقلال با هم می‌آیند.';
  else if(indep) msg = '$P(A\\cap B)='+V.c.toFixed(3)+'$ و $P(A)P(B)='+(V.a*V.b).toFixed(3)+'$ — عملاً برابرند، پس مستقل‌اند. '+
    'توجه کنید که اشتراکشان <b>ناتهی</b> است؛ استقلال دربارهٔ اندازه است، نه دربارهٔ تهی‌بودن اشتراک.';
  else msg = '$P(A\\cap B)='+V.c.toFixed(3)+'$ در حالی که $P(A)P(B)='+(V.a*V.b).toFixed(3)+'$. نه ناسازگار، نه مستقل — '+
    'حالت عمومی. علامت اختلاف می‌گوید کدام جهت: اگر $P(A\\cap B)>P(A)P(B)$ آنگاه $P(A|B)>P(A)$، یعنی $B$ شاهدی <b>به نفع</b> $A$ است.';
  $("#vennVerdict").innerHTML = '<div class="row" style="gap:7px;margin-bottom:7px">'+parts.join("")+'</div>'+
    '<div style="font-size:13.6px">'+msg+'</div>';
  typeset($("#vennVerdict"));
}


/* ==== src/js/instruments/cdf.js ========================================= */

/* ============================================================
   میزکار ۳ — آزمایشگر CDF
   ============================================================ */
var CDFS = {
  disc:{ nm:"CDF گسسته (معتبر)", y:[-0.08,1.12], x:[-3,3],
    jumps:[-1,0,2],
    F:function(x){ return x< -1?0 : x<0?0.2 : x<2?0.7 : 1; },
    d:"متغیر گسسته با $P\\{X=-1\\}=0.2$، $P\\{X=0\\}=0.5$، $P\\{X=2\\}=0.3$. پله‌ای، ناکاهشی، راست‌پیوسته." },
  mix:{ nm:"CDF آمیخته (معتبر)", y:[-0.08,1.12], x:[-2,4],
    jumps:[0],
    F:function(x){ return x<0?0 : 1-0.6*Math.exp(-2*x); },
    d:"تأخیر صف: با احتمال $0.4$ صف خالی است ($T=0$) و در غیر این صورت نمایی با $\\lambda=2$. پرش در صفر + صعود هموار." },
  cont:{ nm:"CDF پیوسته (معتبر)", y:[-0.08,1.12], x:[-4,4],
    jumps:[],
    F:function(x){ return 1/(1+Math.exp(-1.6*x)); },
    d:"هیچ پرشی ندارد، پس $P\\{X=a\\}=0$ برای هر $a$. هر چهار نوع بازه یک احتمال می‌دهند." },
  neg:{ nm:"−⌊x⌋ : نزولی و ناپیوسته", y:[-3.4,3.4], x:[-3,3],
    jumps:[-2,-1,0,1,2,3],
    F:function(x){ return -Math.floor(x); },
    d:"<b>CDF نیست</b> — و همین پاسخ پرسش استاد است: تابع نزولی و ناپیوسته به‌سادگی وجود دارد. اما پرش‌هایش <b>رو به پایین</b>اند و این با یکنوایی $P$ ناسازگار است." },
  down:{ nm:"CDF قلابی: پرش رو به پایین", y:[-0.08,1.12], x:[-3,3],
    jumps:[-1,0,2],
    F:function(x){ return x< -1?0 : x<0?0.6 : x<2?0.3 : 1; },
    d:"<b>CDF نیست.</b> در $x=0$ از $0.6$ به $0.3$ می‌افتد. اگر چنین $F$ای وجود داشت، $P\\{0<X\\le 2\\}=F(2^-)-F(0^-)=0.3-0.6=-0.3<0$ می‌شد — نقض اصل اول کلموگروف." },
  left:{ nm:"CDF قلابی: چپ‌پیوسته", y:[-0.08,1.12], x:[-3,3],
    jumps:[-1,0,2], lc:true,
    F:function(x){ return x<=-1?0 : x<=0?0.2 : x<=2?0.7 : 1; },
    d:"<b>CDF (با قرارداد پاپولیس) نیست.</b> این تابع $P\\{X<x\\}$ را می‌دهد نه $P\\{X\\le x\\}$. ناکاهشی است و حدهایش درست است، اما در نقاط پرش <b>چپ</b>‌پیوسته است. ببینید دایرهٔ تو‌پُر کجا می‌افتد." },
  lim:{ nm:"CDF قلابی: حدها غلط", y:[-1.2,1.2], x:[-3,3],
    jumps:[],
    F:function(x){ return 1-Math.exp(-x); },
    d:"<b>CDF نیست.</b> $F(x)=1-e^{-x}$ روی کل $\\mathbb{R}$: ناکاهشی و پیوسته است، ولی $F(x)\\to-\\infty$ وقتی $x\\to-\\infty$ و مقادیر منفی می‌گیرد — نقض اصل اول و شرط حد." }
};
var CD = {key:"disc", a:1, z:0};

function cdfChecks(k){
  var P = CDFS[k], F=P.F, bad=[];
  var mono=true, lo=-60, hi=60, N=5000, prev=F(lo);
  for(var i=1;i<=N;i++){
    var x = lo + (hi-lo)*i/N, v=F(x);
    if(v < prev - 1e-12){ mono=false; break; }
    prev=v;
  }
  var l0 = F(-1e6), l1 = F(1e6);
  var lim = Math.abs(l0)<1e-6 && Math.abs(l1-1)<1e-6;
  var rc = true;
  (P.jumps||[]).forEach(function(a){
    if(Math.abs(F(a+1e-9)-F(a)) > 1e-6) rc=false;
  });
  var rng = true;
  for(var j=0;j<=400;j++){ var x2=lo+(hi-lo)*j/400, v2=F(x2); if(v2<-1e-9||v2>1+1e-9){ rng=false; break; } }
  return {mono:mono, lim:lim, rc:rc, rng:rng};
}
function renderCdf(){
  $("#cdfPicker").innerHTML = Object.keys(CDFS).map(function(k){
    var bad = /نیست|قلابی|نزولی/.test(CDFS[k].nm+CDFS[k].d) && k!=="disc" && k!=="mix" && k!=="cont";
    return '<button class="btn '+(k===CD.key?"sel":"")+'" style="font-size:12.5px" data-cdf="'+k+'">'+CDFS[k].nm+'</button>';
  }).join("");
  $("#cdfPicker").querySelectorAll("[data-cdf]").forEach(function(b){
    b.addEventListener("click", function(){
      CD.key=b.getAttribute("data-cdf");
      var P=CDFS[CD.key];
      CD.a = (P.jumps&&P.jumps.length)? P.jumps[0] : 0;
      CD.z = 0;
      var s=$("#cdfA"); s.min=P.x[0]; s.max=P.x[1]; s.value=CD.a;
      renderCdf();
    });
  });
  var P = CDFS[CD.key], F=P.F;
  var s=$("#cdfA"); s.min=P.x[0]; s.max=P.x[1];
  CD.a = Math.min(P.x[1], Math.max(P.x[0], CD.a));
  s.value = CD.a;
  $("#cdfZ").value = CD.z;
  $("#cdfAv").textContent = CD.a.toFixed(3);
  var zf = Math.pow(10, -CD.z/40);
  $("#cdfZv").textContent = "×"+(1/zf).toFixed(zf>0.1?1:0);
  drawCdf();

  var h = 1e-9, Fa=F(CD.a), Fm=F(CD.a-h), Fp=F(CD.a+h), jump=Fa-Fm;
  $("#cdfReadout").innerHTML = [
    ro("$F(a^-)$", Fm.toFixed(4)),
    ro("$F(a)$", Fa.toFixed(4)),
    ro("$F(a^+)$", Fp.toFixed(4)),
    ro("$F(a)-F(a^-)$", jump.toFixed(4)),
    ro("$F(a^+)-F(a)$", (Fp-Fa).toFixed(4))
  ].join("");
  typeset($("#cdfReadout"));

  var c = cdfChecks(CD.key);
  var ok = c.mono && c.lim && c.rc && c.rng;
  $("#cdfVerdict").innerHTML =
    '<div class="row" style="gap:7px">'+
      '<span class="pill '+(c.mono?"ok":"no")+'">ناکاهشی '+(c.mono?"✓":"✗")+'</span>'+
      '<span class="pill '+(c.rc?"ok":"no")+'">راست‌پیوسته '+(c.rc?"✓":"✗")+'</span>'+
      '<span class="pill '+(c.lim?"ok":"no")+'">حدهای ۰ و ۱ '+(c.lim?"✓":"✗")+'</span>'+
      '<span class="pill '+(c.rng?"ok":"no")+'">مقادیر در [0,1] '+(c.rng?"✓":"✗")+'</span>'+
      '<span class="pill '+(ok?"ok":"no")+'" style="font-weight:600">'+(ok?"CDF معتبر است":"CDF نیست")+'</span>'+
    '</div>';
  var why = '<div class="'+(ok?"note":"warnbox")+'" style="margin:0"><span class="lbl">'+P.nm+'</span>'+P.d;
  if(jump>1e-6) why += '<br><br>در $a='+CD.a.toFixed(3)+'$ ارتفاع پرش $'+jump.toFixed(3)+
    '$ است. برای یک CDF معتبر این عدد دقیقاً $P\\{X=a\\}$ است.';
  else if(jump< -1e-6) why += '<br><br>در $a='+CD.a.toFixed(3)+'$ پرش <b>منفی</b> است ($'+jump.toFixed(3)+
    '$). برای یک CDF این محال است، چون باید با $P\\{X=a\\}\\ge 0$ برابر می‌شد.';
  why += '</div>';
  $("#cdfWhy").innerHTML = why;
  typeset($("#cdfWhy"));
}
function drawCdf(){
  var o = cv("cdfChart", 290), g=o.g, W=o.w, H=o.h;
  var L=52, R=16, T=16, B=32, pw=W-L-R, ph=H-T-B;
  var P = CDFS[CD.key], F=P.F;
  var mut=tok("--muted"), line=tok("--line"), cont=tok("--cont"), disc=tok("--disc"), ink=tok("--ink"), surf=tok("--surface");
  var zf = Math.pow(10, -CD.z/40);
  var halfW = (P.x[1]-P.x[0])/2 * zf;
  var x0 = CD.a-halfW, x1 = CD.a+halfW;
  var y0 = P.y[0], y1 = P.y[1];
  function X(x){ return L + pw*(x-x0)/(x1-x0); }
  function Y(y){ return T + ph*(1-(y-y0)/(y1-y0)); }

  // grid + axes
  g.font="11px "+(tok("--mono")||"monospace"); g.strokeStyle=line; g.lineWidth=1;
  var yticks = (y1-y0)>3 ? [-3,-2,-1,0,1,2,3] : (y1>1.05? [0,0.25,0.5,0.75,1] : [0,0.25,0.5,0.75,1]);
  yticks.filter(function(t){return t>=y0&&t<=y1;}).forEach(function(t){
    g.strokeStyle = Math.abs(t)<1e-9 ? tok("--line-2") : line;
    g.beginPath(); g.moveTo(L,Y(t)); g.lineTo(W-R,Y(t)); g.stroke();
    g.fillStyle=mut; g.textAlign="right"; g.textBaseline="middle";
    g.fillText(((y1-y0)>3? t.toFixed(0):t.toFixed(2)), L-7, Y(t));
  });
  var nx=6, dec = (x1-x0)<0.02?4:(x1-x0)<0.5?3:(x1-x0)<3?2:1;
  g.textAlign="center"; g.textBaseline="top";
  for(var i=0;i<=nx;i++){
    var xv = x0 + (x1-x0)*i/nx;
    g.strokeStyle=line; g.beginPath(); g.moveTo(X(xv),T); g.lineTo(X(xv),T+ph); g.stroke();
    g.fillStyle=mut; g.fillText(xv.toFixed(dec), X(xv), T+ph+7);
  }

  // curve, with breaks at jumps
  g.strokeStyle=cont; g.lineWidth=2.2; g.beginPath();
  var N=1400, started=false, prevY=null;
  for(var k=0;k<=N;k++){
    var x = x0 + (x1-x0)*k/N, y = F(x);
    if(!isFinite(y)){ started=false; continue; }
    var py = Math.min(Math.max(y,y0),y1);
    if(started && prevY!==null && Math.abs(y-prevY) > (y1-y0)*0.02){
      g.stroke(); g.beginPath(); started=false;
    }
    if(!started){ g.moveTo(X(x),Y(py)); started=true; } else g.lineTo(X(x),Y(py));
    prevY=y;
  }
  g.stroke();

  // jump markers: filled = F(a), hollow = F(a^-)
  (P.jumps||[]).forEach(function(a){
    if(a<x0-1e-12 || a>x1+1e-12) return;
    var Fa=F(a), Fm=F(a-1e-9), Fp=F(a+1e-9);
    g.strokeStyle=line; g.setLineDash([3,3]); g.lineWidth=1;
    g.beginPath(); g.moveTo(X(a),Y(Math.min(Fa,Fm))); g.lineTo(X(a),Y(Math.max(Fa,Fm))); g.stroke(); g.setLineDash([]);
    // hollow at the one-sided limit that differs from F(a)
    g.fillStyle=surf; g.strokeStyle=cont; g.lineWidth=2;
    g.beginPath(); g.arc(X(a),Y(Math.min(Math.max(Fm,y0),y1)),4.4,0,6.284); g.fill(); g.stroke();
    if(Math.abs(Fp-Fa)>1e-7){
      g.beginPath(); g.arc(X(a),Y(Math.min(Math.max(Fp,y0),y1)),4.4,0,6.284); g.fill(); g.stroke();
    }
    g.fillStyle=cont;
    g.beginPath(); g.arc(X(a),Y(Math.min(Math.max(Fa,y0),y1)),4.4,0,6.284); g.fill();
  });

  // the inspection line at a
  g.strokeStyle=disc; g.lineWidth=1.6; g.setLineDash([5,4]);
  g.beginPath(); g.moveTo(X(CD.a),T); g.lineTo(X(CD.a),T+ph); g.stroke(); g.setLineDash([]);
  g.fillStyle=disc; g.textAlign="left"; g.textBaseline="top"; g.font="11px "+(tok("--mono")||"monospace");
  if(X(CD.a) < W-R-40) g.fillText("a="+CD.a.toFixed(dec+1), X(CD.a)+4, T+3);
  else { g.textAlign="right"; g.fillText("a="+CD.a.toFixed(dec+1), X(CD.a)-4, T+3); }

  g.strokeStyle=tok("--line-2"); g.lineWidth=1;
  g.beginPath(); g.moveTo(L,T); g.lineTo(L,T+ph); g.lineTo(W-R,T+ph); g.stroke();

  // legend
  g.font="11px "+(tok("--body")||"sans-serif"); g.textAlign="right"; g.textBaseline="top";
  g.fillStyle=mut;
  g.fillText("● تو‌پُر = F(a)   ○ تو‌خالی = حدِ یک‌طرفه", W-R-2, T+2);
}


/* ==== src/js/instruments/assignment-viz.js ============================== */

/* ---------- نمایش‌های تعاملی ویژهٔ مسائل تمرین ----------
   هر نمایش باید ریاضیاتِ همان مسئله را دقیقاً بازتاب دهد؛ هیچ‌کدام تزئینی نیست. */

var VIZ = {};   /* وضعیت هر نمایش */

function vizHost(id){ return $("#a1Viz-"+id); }

/* ═══════ مسئلهٔ ۳ — شمارش پوآسون، چندک، و دو روز ═══════ */
function poissonPmf(k, lam){
  var lg = -lam + k*Math.log(lam);
  for(var i=2;i<=k;i++) lg -= Math.log(i);
  return Math.exp(lg);
}
function poissonCdf(n, lam){
  var s = 0;
  for(var k=0;k<=n;k++) s += poissonPmf(k, lam);
  return Math.min(1, s);
}
/* کوچک‌ترین n با P{N<=n} >= p  (چندک گسسته) */
function poissonQuantile(p, lam){
  var s = 0;
  for(var k=0;k<2000;k++){
    s += poissonPmf(k, lam);
    if(s >= p - 1e-12) return k;
  }
  return 2000;
}
function drawPoisson(){
  var st = VIZ.pois = VIZ.pois || {rate:144, unit:"month", conf:0.90};
  var host = vizHost("p3"); if(!host) return;
  var per = {month:1/12, week:7/365, day:1/365, two:2/365};
  var lam = st.rate * per[st.unit];
  var n = poissonQuantile(st.conf, lam);
  var atLeast1 = 1 - Math.exp(-lam);

  host.querySelector("[data-pv='rate']").textContent = st.rate;
  host.querySelector("[data-pv='conf']").textContent = (st.conf*100).toFixed(0)+"٪";
  host.querySelector("[data-pout]").innerHTML = [
    ro("$\\lambda$ در این بازه", lam.toFixed(4)),
    ro("چندک مورد نیاز $n$", fa(n)),
    ro("$P\\{N\\le n\\}$", poissonCdf(n, lam).toFixed(5)),
    ro("$P\\{N\\le n-1\\}$", (n>0?poissonCdf(n-1, lam).toFixed(5):"0")),
    ro("$P\\{N\\ge1\\}$", atLeast1.toFixed(5))
  ].join("");
  typeset(host.querySelector("[data-pout]"));

  var o = cv("poisChart", 250), g = o.g, W = o.w, H = o.h;
  var L=46,R=14,T=14,B=30,pw=W-L-R,ph=H-T-B;
  var mut=tok("--muted"), line=tok("--line"), cont=tok("--cont"), disc=tok("--disc"), good=tok("--good");
  var kmax = Math.max(8, Math.ceil(lam + 4*Math.sqrt(lam) + 2));
  var pmax = 0;
  for(var k=0;k<=kmax;k++) pmax = Math.max(pmax, poissonPmf(k, lam));
  pmax = pmax*1.15 || 1;
  function X(k){ return L + pw*(k+0.5)/(kmax+1); }
  function Y(v){ return T + ph*(1 - v/pmax); }
  var bw = Math.max(2, pw/(kmax+1)*0.72);

  g.strokeStyle=line; g.font="11px "+(tok("--mono")||"monospace"); g.fillStyle=mut;
  for(var t=0;t<=4;t++){
    var v = pmax*t/4;
    g.beginPath(); g.moveTo(L,Y(v)); g.lineTo(W-R,Y(v)); g.stroke();
    g.textAlign="right"; g.textBaseline="middle"; g.fillText(v.toFixed(2), L-6, Y(v));
  }
  for(var k2=0;k2<=kmax;k2++){
    var pk = poissonPmf(k2, lam);
    g.fillStyle = k2<=n ? cont : disc;
    g.globalAlpha = k2<=n ? 0.85 : 0.35;
    g.fillRect(X(k2)-bw/2, Y(pk), bw, Y(0)-Y(pk));
    g.globalAlpha = 1;
    if(kmax<=24 || k2%2===0){
      g.fillStyle=mut; g.textAlign="center"; g.textBaseline="top";
      g.fillText(String(k2), X(k2), T+ph+6);
    }
  }
  /* مرز چندک */
  g.strokeStyle=good; g.lineWidth=2; g.setLineDash([5,4]);
  g.beginPath(); g.moveTo(X(n)+bw/2+1, T); g.lineTo(X(n)+bw/2+1, T+ph); g.stroke(); g.setLineDash([]);
  g.fillStyle=good; g.textAlign="right"; g.textBaseline="top"; g.font="11px "+(tok("--body")||"sans-serif");
  g.fillText("n = "+n, X(n)+bw/2-4, T+4);
  g.strokeStyle=tok("--line-2"); g.lineWidth=1;
  g.beginPath(); g.moveTo(L,T); g.lineTo(L,T+ph); g.lineTo(W-R,T+ph); g.stroke();

  host.querySelector("[data-pnote]").innerHTML =
    'ستون‌های پررنگ مجموعاً $P\\{N\\le n\\}='+poissonCdf(n,lam).toFixed(4)+'$ را می‌سازند. '+
    'توجه کنید با یک واحد کمتر، $P\\{N\\le n-1\\}='+(n>0?poissonCdf(n-1,lam).toFixed(4):"0")+'$ است که '+
    'از آستانهٔ خواسته‌شده <b>کمتر</b> می‌ماند — به همین دلیل جواب نامساوی است، نه معادله.';
  typeset(host.querySelector("[data-pnote]"));
}

/* ═══════ مسئله‌های ۶ و ۱۰ — تبدیل متغیر تصادفی ═══════ */
function drawTransform(which){
  var host = vizHost(which); if(!host) return;
  var st = VIZ[which] = VIZ[which] || (which==="p6" ? {lam:1, beta:2} : {lam:2});
  var o = cv("trChart-"+which, 260), g = o.g, W = o.w, H = o.h;
  var L=44,R=14,T=14,B=30,pw=W-L-R,ph=H-T-B;
  var mut=tok("--muted"), line=tok("--line"), cont=tok("--cont"), disc=tok("--disc");

  var fSrc, fDst, gmap, x0, x1, y1, labSrc, labDst;
  if(which==="p6"){
    var lam = st.lam, beta = st.beta;
    x0 = 0; x1 = 4; y1 = 4;
    fSrc = function(x){ return x<0?0: lam*Math.exp(-lam*x); };
    fDst = function(y){ return y<0?0: lam*beta*Math.pow(y, beta-1)*Math.exp(-lam*Math.pow(y, beta)); };
    gmap = function(x){ return Math.pow(Math.max(x,0), 1/beta); };
    labSrc = "f_X — نمایی"; labDst = "f_Y — ویبول";
    host.querySelector("[data-tv='lam']").textContent = lam.toFixed(2);
    host.querySelector("[data-tv='beta']").textContent = beta.toFixed(2);
  } else {
    var l2 = st.lam;
    x0 = -1; x1 = 1; y1 = 3;
    fSrc = function(x){ return (x>=-1&&x<=1)?0.5:0; };
    fDst = function(y){ return y<0?0: l2*Math.exp(-l2*y); };
    gmap = function(x){ return x>=1?Infinity: -Math.log((1-x)/2)/l2; };
    labSrc = "f_X — یکنواخت [-1,1]"; labDst = "f_Y — نمایی";
    host.querySelector("[data-tv='lam']").textContent = l2.toFixed(2);
  }

  var fmax = 0;
  for(var i=0;i<=200;i++){
    fmax = Math.max(fmax, fSrc(x0+(x1-x0)*i/200), fDst(y1*i/200));
  }
  fmax = Math.min(fmax*1.2, 6) || 1;
  function Xp(v, lo, hi){ return L + pw*(v-lo)/(hi-lo); }
  function Yp(v){ return T + ph*(1 - v/fmax); }

  g.strokeStyle=line; g.font="11px "+(tok("--mono")||"monospace"); g.fillStyle=mut;
  for(var t=0;t<=4;t++){
    var yy = T+ph*t/4;
    g.beginPath(); g.moveTo(L,yy); g.lineTo(W-R,yy); g.stroke();
    g.textAlign="right"; g.textBaseline="middle";
    g.fillText((fmax*(1-t/4)).toFixed(1), L-6, yy);
  }
  function curve(f, lo, hi, color, dash){
    g.strokeStyle=color; g.lineWidth=2.2; g.setLineDash(dash||[]);
    g.beginPath();
    var started=false;
    for(var i2=0;i2<=400;i2++){
      var v = lo+(hi-lo)*i2/400, fv = f(v);
      if(!isFinite(fv)) continue;
      var px = Xp(v, lo, hi), py = Yp(Math.min(fv, fmax));
      if(!started){ g.moveTo(px,py); started=true; } else g.lineTo(px,py);
    }
    g.stroke(); g.setLineDash([]);
  }
  curve(fSrc, x0, x1, disc, [5,4]);
  curve(fDst, 0, y1, cont);
  g.font="12px "+(tok("--body")||"sans-serif"); g.textAlign="left"; g.textBaseline="top";
  g.fillStyle=disc; g.fillText(labSrc, L+8, T+4);
  g.fillStyle=cont; g.fillText(labDst, L+8, T+22);
  g.strokeStyle=tok("--line-2"); g.lineWidth=1;
  g.beginPath(); g.moveTo(L,T); g.lineTo(L,T+ph); g.lineTo(W-R,T+ph); g.stroke();
  g.fillStyle=mut; g.font="11px "+(tok("--mono")||"monospace");
  g.textAlign="center"; g.textBaseline="top";
  g.fillText("محور افقی: مقدار متغیر (هر دو چگالی روی یک محور نرمال‌شده رسم شده‌اند)", L+pw/2, T+ph+10);

  /* بررسی عددی نرمال‌سازی — همان آزمونی که در متن توصیه شده */
  var area = 0, NN = 4000;
  for(var j=0;j<NN;j++){
    var yv = y1*(j+0.5)/NN;
    area += fDst(yv)*(y1/NN);
  }
  host.querySelector("[data-tout]").innerHTML = [
    ro("$\\int_0^{"+y1+"} f_Y$", area.toFixed(4)),
    ro("باقی‌ماندهٔ دُم", (1-area).toFixed(4)),
    ro("$g("+(which==="p6"?"1":"0")+")$", (gmap(which==="p6"?1:0)).toFixed(4))
  ].join("");
  typeset(host.querySelector("[data-tout]"));
}

/* ═══════ مسئلهٔ ۱۱ — درخت احتمال و بیز ═══════ */
function drawBayes(){
  var st = VIZ.bayes = VIZ.bayes || {prior:0.5, l1:0.99, l2:0.01};
  var host = vizHost("p11"); if(!host) return;
  var pr = st.prior, l1 = st.l1, l2 = st.l2;
  var j1 = pr*l1, j2 = (1-pr)*l2, pr_ = j1+j2;
  var post = pr_>0 ? j1/pr_ : 0;

  host.querySelector("[data-bv='prior']").textContent = pr.toFixed(3);
  host.querySelector("[data-bv='l1']").textContent = l1.toFixed(3);
  host.querySelector("[data-bv='l2']").textContent = l2.toFixed(3);

  var ink=tok("--ink"), mut=tok("--muted"), cont=tok("--cont"), disc=tok("--disc"), line=tok("--line-2");
  var W=560, H=240;
  function node(x,y,w,h,label,fill){
    return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="7" fill="'+(fill||tok("--surface"))+
      '" stroke="'+line+'"/><text x="'+(x+w/2)+'" y="'+(y+h/2+4)+'" text-anchor="middle" fill="'+ink+
      '" font-size="12">'+label+'</text>';
  }
  function edge(x1,y1,x2,y2,lab,col){
    var mx=(x1+x2)/2, my=(y1+y2)/2;
    return '<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="'+(col||line)+'" stroke-width="1.6"/>'+
      '<text x="'+mx+'" y="'+(my-5)+'" text-anchor="middle" fill="'+(col||mut)+'" font-size="11">'+lab+'</text>';
  }
  /* RTL: ریشه سمت راست */
  var svg =
    node(W-96, H/2-16, 86, 32, "آزمایش") +
    edge(W-96, H/2, W-230, 52, "P(B₁)="+pr.toFixed(2), cont) +
    edge(W-96, H/2, W-230, H-52, "P(B₂)="+(1-pr).toFixed(2), disc) +
    node(W-316, 36, 86, 32, "جعبهٔ ۱") +
    node(W-316, H-68, 86, 32, "جعبهٔ ۲") +
    edge(W-316, 52, W-440, 24, "قرمز "+l1.toFixed(2), cont) +
    edge(W-316, 52, W-440, 80, "سفید "+(1-l1).toFixed(2)) +
    edge(W-316, H-52, W-440, H-80, "قرمز "+l2.toFixed(2), disc) +
    edge(W-316, H-52, W-440, H-24, "سفید "+(1-l2).toFixed(2)) +
    node(W-526, 8, 86, 32, j1.toFixed(4), tok("--cont-soft")) +
    node(W-526, 64, 86, 32, (pr*(1-l1)).toFixed(4)) +
    node(W-526, H-96, 86, 32, j2.toFixed(4), tok("--disc-soft")) +
    node(W-526, H-40, 86, 32, ((1-pr)*(1-l2)).toFixed(4));
  $("#bayesTree").innerHTML = svg;

  /* نوار دقیق: سهم دو مسیر قرمز */
  var BW=520, X0=20, BY=16, BH=34;
  var w1 = pr_>0 ? (j1/pr_)*BW : 0;
  var bar = '<rect x="'+X0+'" y="'+BY+'" width="'+BW+'" height="'+BH+'" fill="'+tok("--surface-2")+'" stroke="'+line+'"/>'+
    '<rect x="'+X0+'" y="'+BY+'" width="'+w1+'" height="'+BH+'" fill="'+cont+'" opacity="0.55"/>'+
    '<rect x="'+(X0+w1)+'" y="'+BY+'" width="'+(BW-w1)+'" height="'+BH+'" fill="'+disc+'" opacity="0.55"/>'+
    '<text x="'+(X0+w1/2)+'" y="'+(BY+BH/2+4)+'" text-anchor="middle" fill="'+ink+'" font-size="12">جعبهٔ ۱ · '+
      (post*100).toFixed(1)+'٪</text>'+
    (BW-w1 > 56 ? '<text x="'+(X0+w1+(BW-w1)/2)+'" y="'+(BY+BH/2+4)+'" text-anchor="middle" fill="'+ink+
      '" font-size="12">جعبهٔ ۲ · '+((1-post)*100).toFixed(1)+'٪</text>' : '');
  $("#bayesBar").innerHTML = bar;

  var oddsPrior = (1-pr)>0 ? pr/(1-pr) : Infinity;
  var lr = l2>0 ? l1/l2 : Infinity;
  host.querySelector("[data-bout]").innerHTML = [
    ro("$P(R)$ کل", pr_.toFixed(5)),
    ro("پسین $P(B_1\\mid R)$", post.toFixed(5)),
    ro("بخت پیشین", isFinite(oddsPrior)?oddsPrior.toFixed(3):"∞"),
    ro("نسبت درست‌نمایی", isFinite(lr)?lr.toFixed(2):"∞"),
    ro("بخت پسین", (isFinite(oddsPrior)&&isFinite(lr))?(oddsPrior*lr).toFixed(2):"∞")
  ].join("");
  typeset(host.querySelector("[data-bout]"));

  var msg;
  if(Math.abs(post-0.5) < 0.02)
    msg = 'پسین تقریباً $0{,}5$ است: شاهد قوی دقیقاً با پیشین ضعیف خنثی شده. '+
          'این همان <b>مغالطهٔ نرخ پایه</b> است — جایی که شهود بیشترین خطا را می‌کند.';
  else if(post > 0.9)
    msg = 'شاهد به‌شدت به نفع جعبهٔ ۱ است. توجه کنید بخت پسین حاصل‌ضرب بخت پیشین در نسبت درست‌نمایی است — '+
          'ضرب‌کردن، از کار با مخرج بیز ساده‌تر است.';
  else
    msg = 'پیشین را به سمت صفر ببرید و ببینید چطور حتی با نسبت درست‌نمایی $99$، پسین سقوط می‌کند. '+
          'این دقیقاً چیزی است که در تست‌های تشخیصی بیماری‌های نادر رخ می‌دهد.';
  host.querySelector("[data-bnote]").innerHTML = msg;
  typeset(host.querySelector("[data-bnote]"));
}

/* ═══════ مسئلهٔ ۵ — چگالی و CDF کنار هم ═══════ */
function drawDensity(){
  var st = VIZ.dens = VIZ.dens || {a:0.25, b:0.75};
  var host = vizHost("p5"); if(!host) return;
  if(st.a > st.b){ var t0 = st.a; st.a = st.b; st.b = t0; }
  var f = function(x){ return (x>=-1&&x<=1) ? 0.75*(1-x*x) : 0; };
  var F = function(x){ return x<-1?0 : x>1?1 : 0.75*(x - x*x*x/3 + 2/3); };
  var prob = F(st.b) - F(st.a);

  host.querySelector("[data-dv='a']").textContent = st.a.toFixed(2);
  host.querySelector("[data-dv='b']").textContent = st.b.toFixed(2);

  var o = cv("densChart", 250), g = o.g, W = o.w, H = o.h;
  var L=44,R=14,T=14,B=28,pw=W-L-R,ph=H-T-B;
  var mut=tok("--muted"), line=tok("--line"), cont=tok("--cont"), disc=tok("--disc");
  var ymax = 1.1;
  function X(x){ return L + pw*(x+1.2)/2.4; }
  function Y(v){ return T + ph*(1 - v/ymax); }

  g.strokeStyle=line;
  for(var t=0;t<=4;t++){
    var v = ymax*t/4;
    g.beginPath(); g.moveTo(L,Y(v)); g.lineTo(W-R,Y(v)); g.stroke();
    g.fillStyle=mut; g.font="11px "+(tok("--mono")||"monospace");
    g.textAlign="right"; g.textBaseline="middle"; g.fillText(v.toFixed(2), L-6, Y(v));
  }
  /* ناحیهٔ شاخص زیر چگالی */
  g.fillStyle=cont; g.globalAlpha=0.26; g.beginPath(); g.moveTo(X(st.a), Y(0));
  for(var i=0;i<=120;i++){ var xv = st.a + (st.b-st.a)*i/120; g.lineTo(X(xv), Y(f(xv))); }
  g.lineTo(X(st.b), Y(0)); g.closePath(); g.fill(); g.globalAlpha=1;
  /* چگالی */
  g.strokeStyle=cont; g.lineWidth=2.3; g.beginPath();
  for(var i2=0;i2<=400;i2++){ var x2=-1.2+2.4*i2/400; var px=X(x2), py=Y(f(x2)); i2?g.lineTo(px,py):g.moveTo(px,py); }
  g.stroke();
  /* CDF */
  g.strokeStyle=disc; g.lineWidth=2; g.setLineDash([6,4]); g.beginPath();
  for(var i3=0;i3<=400;i3++){ var x3=-1.2+2.4*i3/400; var px3=X(x3), py3=Y(F(x3)); i3?g.lineTo(px3,py3):g.moveTo(px3,py3); }
  g.stroke(); g.setLineDash([]);
  /* خط‌های a و b */
  [[st.a,"a"],[st.b,"b"]].forEach(function(p){
    g.strokeStyle=mut; g.lineWidth=1; g.setLineDash([3,3]);
    g.beginPath(); g.moveTo(X(p[0]),T); g.lineTo(X(p[0]),T+ph); g.stroke(); g.setLineDash([]);
  });
  g.font="12px "+(tok("--body")||"sans-serif"); g.textAlign="left"; g.textBaseline="top";
  g.fillStyle=cont; g.fillText("f_X(x)", L+8, T+4);
  g.fillStyle=disc; g.fillText("F_X(x)", L+8, T+22);
  g.strokeStyle=tok("--line-2"); g.lineWidth=1;
  g.beginPath(); g.moveTo(L,T); g.lineTo(L,T+ph); g.lineTo(W-R,T+ph); g.stroke();
  g.fillStyle=mut; g.font="11px "+(tok("--mono")||"monospace");
  g.textAlign="center"; g.textBaseline="top";
  [-1,-0.5,0,0.5,1].forEach(function(x){ g.fillText(String(x), X(x), T+ph+6); });

  host.querySelector("[data-dout]").innerHTML = [
    ro("$F_X(a)$", F(st.a).toFixed(5)),
    ro("$F_X(b)$", F(st.b).toFixed(5)),
    ro("$P\\{a<X<b\\}$", prob.toFixed(5)),
    ro("مساحت سایه‌زده", prob.toFixed(5)),
    ro("$f_X$ در وسط بازه", f((st.a+st.b)/2).toFixed(4))
  ].join("");
  typeset(host.querySelector("[data-dout]"));
  host.querySelector("[data-dnote]").innerHTML =
    'سطح سایه‌زده زیر چگالی، دقیقاً برابر پرش $F$ بین همان دو نقطه است — هر دو عدد بالا یکی‌اند. '+
    'بازه را با طول ثابت جابه‌جا کنید و ببینید هرچه از مرکز دورتر شوید احتمال کمتر می‌شود، '+
    'در حالی که <b>طول بازه تغییر نکرده</b>. همین نشان می‌دهد چرا چگالی احتمال نیست.';
  typeset(host.querySelector("[data-dnote]"));
}

/* ═══════ راه‌انداز ═══════ */
function drawA1Instruments(id){
  if(id==="p3") drawPoisson();
  else if(id==="p5") drawDensity();
  else if(id==="p6") drawTransform("p6");
  else if(id==="p10") drawTransform("p10");
  else if(id==="p11") drawBayes();
}
/* نشانهٔ اینکه کدام مسئله نمایش تعاملی دارد */
var A1_VIZ = {
  p3:{title:"آزمایشگاه پوآسون — چندک و احتمال دُم", tag:"quantile · rate scaling"},
  p5:{title:"چگالی و CDF کنار هم", tag:"area = ΔF"},
  p6:{title:"تبدیل نمایی به ویبول", tag:"change of variable"},
  p10:{title:"تبدیل یکنواخت به نمایی", tag:"inverse transform"},
  p11:{title:"درخت احتمال و بخت پسین", tag:"prior × likelihood"}
};
function a1VizMarkup(id){
  var v = A1_VIZ[id]; if(!v) return "";
  var ctrls = "";
  if(id==="p3") ctrls =
    '<div class="row">'+
      '<label class="ctl">نرخ سالانه <span class="v" data-pv="rate"></span>'+
        '<input type="range" id="pRate" min="12" max="600" step="12" value="144"></label>'+
      '<label class="ctl">سطح اطمینان <span class="v" data-pv="conf"></span>'+
        '<input type="range" id="pConf" min="0.5" max="0.99" step="0.01" value="0.9"></label>'+
    '</div>'+
    '<div class="row" style="margin-top:8px">'+
      '<button class="btn" data-punit="month">یک ماه</button>'+
      '<button class="btn" data-punit="week">یک هفته</button>'+
      '<button class="btn" data-punit="two">دو روز</button>'+
      '<button class="btn" data-punit="day">یک روز</button>'+
    '</div>'+
    '<div class="cvswrap" style="margin-top:12px"><canvas id="poisChart" height="250"></canvas></div>'+
    '<div class="readout" data-pout></div><p style="font-size:13.4px;margin:10px 0 0" data-pnote></p>';
  if(id==="p5") ctrls =
    '<div class="row">'+
      '<label class="ctl">کران پایین a = <span class="v" data-dv="a"></span>'+
        '<input type="range" id="dA" min="-1" max="1" step="0.01" value="0.25"></label>'+
      '<label class="ctl">کران بالا b = <span class="v" data-dv="b"></span>'+
        '<input type="range" id="dB" min="-1" max="1" step="0.01" value="0.75"></label>'+
    '</div>'+
    '<div class="cvswrap" style="margin-top:12px"><canvas id="densChart" height="250"></canvas></div>'+
    '<div class="readout" data-dout></div><p style="font-size:13.4px;margin:10px 0 0" data-dnote></p>';
  if(id==="p6") ctrls =
    '<div class="row">'+
      '<label class="ctl">$\\lambda$ = <span class="v" data-tv="lam"></span>'+
        '<input type="range" id="t6lam" min="0.2" max="3" step="0.05" value="1"></label>'+
      '<label class="ctl">$\\beta$ (شکل) = <span class="v" data-tv="beta"></span>'+
        '<input type="range" id="t6beta" min="0.3" max="4" step="0.05" value="2"></label>'+
    '</div>'+
    '<div class="cvswrap" style="margin-top:12px"><canvas id="trChart-p6" height="260"></canvas></div>'+
    '<div class="readout" data-tout></div>'+
    '<p style="font-size:13.4px;margin:10px 0 0">$\\beta$ را روی ۱ بگذارید: ویبول دقیقاً به نمایی برمی‌گردد '+
    'و دو منحنی بر هم منطبق می‌شوند — همان آزمون حالت خاصی که در متن حل توصیه شد.</p>';
  if(id==="p10") ctrls =
    '<div class="row">'+
      '<label class="ctl">$\\lambda$ مقصد = <span class="v" data-tv="lam"></span>'+
        '<input type="range" id="t10lam" min="0.3" max="4" step="0.05" value="2"></label>'+
    '</div>'+
    '<div class="cvswrap" style="margin-top:12px"><canvas id="trChart-p10" height="260"></canvas></div>'+
    '<div class="readout" data-tout></div>'+
    '<p style="font-size:13.4px;margin:10px 0 0">چگالی یکنواخت تخت است و چگالی مقصد نمایی؛ '+
    '$g$ باید جرم را از یک بازهٔ کران‌دار روی یک نیم‌خط بی‌کران پخش کند و این کار را با کشیدن '+
    'شدید نزدیک $x=1$ انجام می‌دهد.</p>';
  if(id==="p11") ctrls =
    '<div class="row">'+
      '<label class="ctl">پیشین $P(B_1)$ = <span class="v" data-bv="prior"></span>'+
        '<input type="range" id="bPrior" min="0.001" max="0.999" step="0.001" value="0.5"></label>'+
      '<label class="ctl">$P(R\\mid B_1)$ = <span class="v" data-bv="l1"></span>'+
        '<input type="range" id="bL1" min="0" max="1" step="0.005" value="0.99"></label>'+
      '<label class="ctl">$P(R\\mid B_2)$ = <span class="v" data-bv="l2"></span>'+
        '<input type="range" id="bL2" min="0" max="1" step="0.005" value="0.01"></label>'+
    '</div>'+
    '<div class="cvswrap" style="margin-top:12px"><svg id="bayesTree" width="560" height="240" role="img" aria-label="درخت احتمال بیز"></svg></div>'+
    '<div class="cvswrap"><svg id="bayesBar" width="560" height="64" role="img" aria-label="نوار سهم پسین"></svg></div>'+
    '<div class="readout" data-bout></div><p style="font-size:13.4px;margin:10px 0 0" data-bnote></p>';
  return '<div class="bench" id="a1Viz-'+id+'"><header><h4>'+v.title+'</h4>'+
    '<span class="tag">'+v.tag+'</span></header><div class="pad">'+ctrls+'</div></div>';
}
/* اتصال کنترل‌ها پس از رندر میزکار */
function a1VizBind(id){
  function on(sel, fn){ var el = $(sel); if(el) el.addEventListener("input", fn); }
  if(id==="p3"){
    on("#pRate", function(){ VIZ.pois.rate = +this.value; drawPoisson(); });
    on("#pConf", function(){ VIZ.pois.conf = +this.value; drawPoisson(); });
    $$("[data-punit]").forEach(function(b){
      b.addEventListener("click", function(){
        VIZ.pois.unit = b.getAttribute("data-punit");
        $$("[data-punit]").forEach(function(x){ x.classList.remove("sel"); });
        b.classList.add("sel");
        drawPoisson();
      });
    });
  }
  if(id==="p5"){
    on("#dA", function(){ VIZ.dens.a = +this.value; drawDensity(); });
    on("#dB", function(){ VIZ.dens.b = +this.value; drawDensity(); });
  }
  if(id==="p6"){
    on("#t6lam", function(){ VIZ.p6.lam = +this.value; drawTransform("p6"); });
    on("#t6beta", function(){ VIZ.p6.beta = +this.value; drawTransform("p6"); });
  }
  if(id==="p10") on("#t10lam", function(){ VIZ.p10.lam = +this.value; drawTransform("p10"); });
  if(id==="p11"){
    on("#bPrior", function(){ VIZ.bayes.prior = +this.value; drawBayes(); });
    on("#bL1", function(){ VIZ.bayes.l1 = +this.value; drawBayes(); });
    on("#bL2", function(){ VIZ.bayes.l2 = +this.value; drawBayes(); });
  }
  drawA1Instruments(id);
}


/* ==== src/js/instruments/wiring.js ====================================== */

/* ---------- wiring ---------- */
["vPA","vPB","vPAB"].forEach(function(id){
  var el=$("#"+id); if(!el) return;
  el.addEventListener("input", function(){
    V.a=+$("#vPA").value; V.b=+$("#vPB").value; V.c=+$("#vPAB").value;
    renderVenn();
  });
});
$$("[data-run]").forEach(function(b){
  b.addEventListener("click", function(){ exRun(+b.getAttribute("data-run")); });
});
$("#expReset").addEventListener("click", function(){ EX.n=0; EX.nA=0; EX.hist=[]; drawExp(); fillExpReadout(); });
$("#cdfA").addEventListener("input", function(){ CD.a=+this.value; renderCdf(); });
$("#cdfZ").addEventListener("input", function(){ CD.z=+this.value; renderCdf(); });

var rz=null;
window.addEventListener("resize", function(){
  clearTimeout(rz); rz=setTimeout(function(){ drawExp(); drawCdf(); renderVenn(); }, 140);
});
$("#themeBtn").addEventListener("click", function(){
  setTimeout(function(){ drawExp(); drawCdf(); renderVenn(); }, 30);
});

renderExp();
renderVenn();
renderCdf();
